// Desktop OS – Deel II: Windows – Werkcollege 2
// v = vraag, a = antwoord, o = onderwerp, uitleg = extra uitleg, img/imgAntwoord = afbeelding (map afbeeldingen/)
// wit: true = witte kaart die de cursus voorstelt · extra: true = extra info, niet uit de cursus (turquoise rand)
// oefening: true = blauwe oefenkaart: typ het commando. In a staan commando's na "$ "; regels die met 2 spaties beginnen zijn toetsen of uitvoer.
// De structuur onderaan bepaalt het overzicht rechts.

const kaarten_DOS_windows_wc2 = [
  // ===== PC-naam =====
  { v: "PC-naam", a: "• De PC-naam is belangrijk: zo herken je de pc's in je netwerk, en zo identificeert de domain controller jouw pc.\n• Namen moeten uniek zijn, anders krijg je overlappingen en problemen op je domein.\n• Bij elke Windows-installatie kies je een PC-naam; je kan hem op verschillende manieren veranderen.\n• Rechtsklik op de startknop: een overzicht van veel gebruikte tools.\n• Wijzigen: System Settings → System → About → Rename this PC.", o: "PC-naam", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_rename_pc.jpg",
    uitleg: "Wat is de PC-naam? Elke Windows-computer heeft een naam, bv. LAPTOP-ANICEE. Op een netwerk zien andere computers jouw pc onder die naam, in plaats van enkel een IP-adres.\n\nDomain controller = de server die in een bedrijf of school alle computers en gebruikersaccounts beheert (meer daarover bij \"Werkgroep en domein\"). Hij herkent jouw pc aan de PC-naam.\n\nUniek: als twee pc's dezelfde naam hebben, weet het netwerk niet welke bedoeld wordt. Dan krijg je fouten, bv. de verkeerde pc die regels of bestanden krijgt.\n\nRechtsklik op de startknop opent een menu met snelkoppelingen naar beheerstools: System, Device Manager, Disk Management, Task Manager, Network Connections enzovoort. Je gebruikt dat menu in dit werkcollege heel vaak.\n\nNa het wijzigen van de PC-naam moet je de pc herstarten: Windows gebruikt de nieuwe naam pas na een herstart." },
  { v: "Waarom is de PC-naam belangrijk?", a: "Zo herken je makkelijk de pc's in je netwerk, en zo identificeert je domain controller jouw pc.", o: "PC-naam",
    uitleg: "Op een netwerk hangen vaak tientallen of honderden pc's. Een naam zoals JAN-PEETERS-VM zegt meteen welke pc het is; een IP-adres (bv. 10.0.4.27) niet, en dat kan bovendien veranderen.\n\nIn een domein houdt de domain controller (de server die alle pc's beheert) een lijst bij van alle pc's die erbij horen. Hij gebruikt de PC-naam om jouw pc te herkennen en de juiste regels en instellingen te geven." },
  { v: "Waarom moeten PC-namen uniek zijn?", a: "Om overlappingen en problemen op je domein te vermijden.", o: "PC-naam",
    uitleg: "Het netwerk en de domain controller zoeken een pc op aan zijn naam. Hebben twee pc's dezelfde naam, dan weet het netwerk niet welke van de twee bedoeld wordt.\n\nGevolgen: een pc kan zijn plaats in het domein verliezen, regels of bestanden komen bij de verkeerde pc terecht, of verbinden lukt niet meer. Daarom geef je elke pc een eigen naam, bv. met je voornaam en familienaam erin, zoals de opdracht vraagt." },
  { v: "Wat opent een rechtsklik op de startknop?", a: "Een overzicht van verschillende tools en opties die je vaak nodig hebt in Windows.", o: "PC-naam",
    uitleg: "Rechtsklik op de startknop (het Windows-logo onderaan) opent een menu met snelkoppelingen naar beheerstools: o.a. System, Device Manager, Network Connections, Disk Management, Computer Management, Terminal en Task Manager.\n\nHandig om te onthouden: je kan dit menu ook openen met de toetsen Windows + X.\n\nVeel opdrachten in dit werkcollege beginnen met deze rechtsklik." },
  { v: "Verander de naam van je VM naar <voornaam>-<verkorte familienaam>-VM.", a: "Rechtsklik op de startknop → System → About → Rename this PC", o: "PC-naam", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_rename_pc.jpg",
    uitleg: "Stap voor stap:\n1. Rechtsklik op de startknop en kies System.\n2. In het venster System kies je About (info over je pc).\n3. Klik op Rename this PC.\n4. Typ de nieuwe naam, bv. jan-peeters-VM, en bevestig.\n5. Herstart de pc: Windows gebruikt de nieuwe naam pas na een herstart.\n\nEen PC-naam mag geen spaties en geen speciale tekens bevatten; een liggend streepje (-) mag wel." },
  // ===== Werkgroep en domein =====
  { v: "Werkgroep en domein", a: "• Werkgroep: een verzameling pc's binnen een netwerk. Ze kunnen bronnen delen (printers, scanners, folders, bestanden); de werkgroep toont dat duidelijker, maar biedt verder geen meerwaarde. Geen controle: iedereen kan erin.\n• Domein: ook een verzameling computers, maar beheerd door een Domain Controller. Je draagt de controle over: internetregels, wallpaper, software installeren, pc-instellingen en accounts.\n• Een domein is beveiligd: folders, bestanden en andere resources worden veilig gedeeld.", o: "Werkgroep en domein", wit: true,
    uitleg: "Wat is een werkgroep? Een groep pc's op hetzelfde netwerk die elkaar zien en dingen kunnen delen, bv. een printer of een map. Elke pc beheert zichzelf: elke pc heeft zijn eigen gebruikersaccounts, en niemand heeft het overzicht. Zo werkt het meestal thuis.\n\nWat is een domein? Ook een groep computers, maar centraal beheerd door één server: de Domain Controller. Die houdt alle gebruikersaccounts en regels bij. Je logt in met één account dat op elke pc van het domein werkt. Zo werkt het in bedrijven en scholen.\n\nControle overdragen betekent: de beheerder van het domein bepaalt vanop de Domain Controller hoe jouw pc werkt, bv. welke websites je mag bezoeken, welke wallpaper je krijgt en of je zelf software mag installeren.\n\nBeveiligd: in een domein beslist de Domain Controller wie welke map of printer mag gebruiken. In een werkgroep is er geen centrale controle." },
  { v: "Wat is een werkgroep?", a: "Een verzameling pc's binnen een bepaald netwerk, die bronnen kunnen delen (printers, scanners, folders, bestanden).", o: "Werkgroep en domein",
    uitleg: "Een werkgroep is de eenvoudigste manier om pc's samen te laten werken op een netwerk, bv. thuis.\n\nBronnen delen = iets van je eigen pc beschikbaar maken voor de andere pc's: een printer, een scanner, een map of een bestand.\n\nElke pc in een werkgroep beheert zichzelf: elke pc heeft zijn eigen gebruikersaccounts. Er is geen centrale server." },
  { v: "Welke meerwaarde en welke controle biedt een werkgroep?", a: "Ze toont de gedeelde bronnen duidelijker, maar biedt verder geen meerwaarde. Er is geen enkele controle: iedereen kan in een werkgroep komen.", o: "Werkgroep en domein",
    uitleg: "Meerwaarde: een werkgroep groepeert de pc's onder één naam, zodat je de gedeelde printers en mappen overzichtelijker ziet. Meer doet ze niet.\n\nGeen controle: er is geen centrale server die bepaalt wie erbij mag. Elke pc kan zich gewoon bij een werkgroep zetten door de naam van de werkgroep in te vullen, en niemand kan regels opleggen aan de pc's.\n\nDaarom is een werkgroep goed voor een klein netwerk thuis, maar niet voor een bedrijf." },
  { v: "Wat is een domein?", a: "Een verzameling computers die beheerd worden door een Domain Controller.", o: "Werkgroep en domein",
    uitleg: "Een domein is een groep computers die centraal beheerd wordt.\n\nDe Domain Controller is een server (een Windows Server met Active Directory) die bijhoudt:\n• welke computers bij het domein horen;\n• welke gebruikers er zijn, met hun wachtwoord;\n• welke regels gelden (bv. wie wat mag).\n\nJe logt in met je domeinaccount, en dat werkt op elke pc van het domein. Zo werkt het bv. op school en in bedrijven." },
  { v: "Wat betekent het als je pc deel uitmaakt van een domein? Geef voorbeelden.", a: "Je draagt de controle over aan de Domain Controller: bv. internetregels, de wallpaper, software installeren, pc-instellingen en accounts wijzigen.", o: "Werkgroep en domein",
    uitleg: "Zodra je pc lid is van een domein, beslist de beheerder (via de Domain Controller) mee over je pc. Jij bent dan niet meer de enige baas.\n\nVoorbeelden uit de cursus:\n• internetregels: welke websites je mag bezoeken;\n• de wallpaper: de achtergrond van je bureaublad;\n• software installeren: of je dat zelf mag;\n• pc-instellingen en accounts: wie mag inloggen en wat hij mag aanpassen.\n\nDe beheerder stelt die regels één keer in op de Domain Controller, en ze gelden voor alle pc's in het domein." },
  { v: "Wat is het grote verschil tussen een werkgroep en een domein?", a: "Een domein is beveiligd en deelt folders, bestanden en resources op een beveiligde manier; een werkgroep heeft geen controle.", o: "Werkgroep en domein",
    uitleg: "Werkgroep: elke pc beheert zichzelf. Er is geen centrale controle: iedereen kan erbij, en de regels voor delen stelt elke pc zelf in.\n\nDomein: één server (de Domain Controller) beheert alles. Hij controleert wie inlogt (met een wachtwoord) en wie welke map, welk bestand of welke printer mag gebruiken. Daarom zegt de cursus: een domein deelt resources op een beveiligde manier." },
  // ===== DNS =====
  { v: "DNS", a: "• DNS = Domain Name System: vertaalt domeinnamen (zoals google.com) naar IP-adressen (zoals 142.250.74.14).\n• Computers werken met IP-adressen, mensen onthouden makkelijker namen.\n• Opdracht: surf naar http://desktoposisawesome.be (bestaat niet), verander je DNS en surf opnieuw: nu werkt het.\n• De DNS-server van de opdracht is enkel zichtbaar binnen het schoolnetwerk: verbind via VPN.\n• Wijzigen: rechtsklik startknop → Network Connections → Ethernet → DNS server assignment → manueel, voor IPv4.\n• In hetzelfde venster pas je ook het IP-adres, het subnet mask en de default gateway aan.", o: "DNS", wit: true,
    uitleg: "Het adres van de DNS-server van de school staat in de cursus; ik zet het bewust niet op de kaart." },
  { v: "Waarvoor staat DNS, en wat doet het?", a: "Domain Name System: het vertaalt domeinnamen (zoals google.com) naar IP-adressen (zoals 142.250.74.14).", o: "DNS",
    uitleg: "DNS = Domain Name System.\n\nOp een netwerk vinden computers elkaar via IP-adressen: getallen zoals 142.250.74.14. Een domeinnaam zoals google.com is de naam die bij zo'n adres hoort.\n\nTyp je google.com in je browser, dan gebeurt dit:\n1. Je pc vraagt aan een DNS-server: \"welk IP-adres hoort bij google.com?\"\n2. De DNS-server antwoordt met het IP-adres.\n3. Je pc maakt verbinding met dat IP-adres.\n\nDNS-server = een computer die die lijst van namen en IP-adressen bijhoudt en vragen beantwoordt. Welke DNS-server jouw pc gebruikt, stel je in bij de netwerkinstellingen (zie de andere DNS-kaarten).\n\nTest het zelf in cmd: nslookup google.com toont het IP-adres dat de DNS-server teruggeeft." },
  { v: "Waarom bestaat DNS?", a: "Computers werken met IP-adressen, maar mensen onthouden makkelijker namen. Zo bezoek je een website door een naam te typen.", o: "DNS",
    uitleg: "Computers werken met IP-adressen: getallen zoals 142.250.74.14. Die zijn moeilijk te onthouden. Namen zoals google.com of ehb.be zijn makkelijker.\n\nDNS koppelt die twee: jij typt de naam, je pc vraagt aan de DNS-server het bijhorende IP-adres en maakt daarmee verbinding.\n\nEen tweede voordeel: verandert het IP-adres van een server (bv. omdat de website naar een andere server verhuist), dan past men het alleen aan in DNS. De naam blijft dezelfde, dus jij merkt er niets van." },
  { v: "Waarom moet je voor de DNS-opdracht met VPN verbonden zijn?", a: "De DNS-server is enkel zichtbaar binnen het schoolnetwerk.", o: "DNS",
    uitleg: "De DNS-server van de opdracht staat in het netwerk van de school. Hij is niet bereikbaar vanaf het gewone internet.\n\nVPN (Virtual Private Network) = een beveiligde verbinding van jouw pc naar het netwerk van de school, via het internet. Ben je met de VPN verbonden, dan gedraagt je pc zich alsof hij op school in het netwerk zit, en kan hij die DNS-server bereiken.\n\nZonder VPN krijgt je pc geen antwoord van die DNS-server: namen worden niet vertaald en de opdracht lukt niet." },
  { v: "Wat kan je nog aanpassen in hetzelfde venster als de DNS-server?", a: "Het IP-adres, het subnet mask en de default gateway.", o: "DNS",
    uitleg: "Het IP-adres, het subnet mask en de default gateway. Ze staan in hetzelfde venster (Internet Protocol Version 4 (TCP/IPv4) → Properties) omdat ze samen bepalen hoe je pc op het netwerk werkt:\n\n1. IP-adres: het adres van je eigen pc op het netwerk, bv. 192.168.1.20.\n2. Subnet mask: bepaalt welk deel van het IP-adres het netwerk aanduidt, bv. 255.255.255.0. Daarmee weet je pc welke adressen in zijn eigen netwerk liggen (die kan hij rechtstreeks bereiken) en welke daarbuiten.\n3. Default gateway: het adres van de router. Alles wat naar buiten je eigen netwerk moet (bv. naar het internet), stuurt je pc daarnaartoe.\n4. DNS-server: de server die namen naar IP-adressen vertaalt.\n\nIn dat venster kies je ook:\n- Obtain an IP address automatically: de pc krijgt alles automatisch van een DHCP-server (meestal de router).\n- Use the following IP address: je vult alles zelf in (een vast of statisch IP-adres).\n\nDHCP = de dienst die automatisch IP-adressen en de andere instellingen uitdeelt aan pc's op het netwerk." },
  { v: "Wat doet je computer als je een naam zoals desktoposisawesome.be intypt?", a: "Hij vraagt aan zijn DNS-server welk IP-adres bij die naam hoort, en maakt daarna verbinding met dat IP-adres.", o: "DNS",
    uitleg: "Een computer op het internet is enkel bereikbaar via zijn IP-adres. De naam is er voor mensen.\nJe computer stuurt de naam naar de DNS-server en krijgt het IP-adres terug. Pas daarna maakt de browser verbinding met dat IP-adres.\nZonder IP-adres weet je computer niet waar de website staat." },
  { v: "Waarom werkt http://desktoposisawesome.be eerst niet, en na het aanpassen van je DNS wel?", a: "De naam staat enkel in de DNS-server van de school. Je gewone DNS-server kent de naam niet en geeft geen IP-adres terug. Daarom wijs je je computer de DNS-server van de school toe.", o: "DNS",
    uitleg: "Elke DNS-server kent enkel de namen die erin staan, of die hij bij andere DNS-servers kan opvragen.\ndesktoposisawesome.be is niet echt op het internet geregistreerd: de naam staat enkel in de DNS-server van de school.\nJe gewone DNS-server antwoordt dus: deze naam bestaat niet. De browser toont dan een fout." },
  { v: "Wat betekent DNS server assignment: Automatic (DHCP)?", a: "Je computer krijgt het adres van de DNS-server automatisch van het netwerk (de DHCP-server, thuis meestal je router). Dat is de standaardinstelling. Bij Manual vul je het zelf in.", o: "DNS", extra: true,
    uitleg: "DHCP is de dienst die je computer automatisch netwerkinstellingen geeft als hij met een netwerk verbindt: een IP-adres, het subnet mask, de default gateway en de DNS-server. Daarom moet je thuis niets instellen om te kunnen surfen.\nKies je Manual, dan gebruikt je computer voor de DNS niet meer wat DHCP geeft, maar wat jij invult." },
  { v: "Wat is het verschil tussen Preferred DNS en Alternate DNS?", a: "Preferred DNS = de DNS-server die je computer eerst vraagt. Alternate DNS = de reserve, als de eerste niet antwoordt.", o: "DNS", extra: true,
    uitleg: "Je computer stuurt elke vraag eerst naar de Preferred DNS. Enkel als die niet antwoordt (bv. omdat hij niet bereikbaar is), probeert hij de Alternate DNS.\nZo blijven namen werken als één DNS-server uitvalt." },
  { v: "Waarom zet je bij Manual IPv4 aan?", a: "Het adres van de DNS-server van de opdracht is een IPv4-adres. IPv4 en IPv6 hebben elk hun eigen DNS-instelling.", o: "DNS",
    uitleg: "Een IPv4-adres bestaat uit vier getallen met punten, bv. 192.168.1.10. Een IPv6-adres is veel langer, met dubbele punten.\nIn het venster heb je een schakelaar voor IPv4 en een voor IPv6, elk met eigen vakjes. Het adres van de school-DNS heeft de vorm van een IPv4-adres, dus vul je het in bij IPv4." },
  { v: "Waarom zet je de DNS na de opdracht best terug op Automatic (DHCP)?", a: "De DNS-server van de school is enkel bereikbaar via VPN. Zonder VPN kan je computer dan geen namen meer vertalen, en werken websites niet meer.", o: "DNS", extra: true,
    uitleg: "Na Manual vraagt je computer elke naam, ook google.com, aan de DNS-server van de school.\nDie is enkel bereikbaar als de VPN aanstaat. Zet je de VPN uit, dan krijgt je computer op geen enkele naam nog een antwoord.\nHet lijkt dan alsof je internet niet werkt, terwijl enkel de DNS het probleem is." },
  { v: "Waar zie je in de CLI welke DNS-server je computer nu gebruikt?", a: "In de uitvoer van ipconfig /all, bij de regel DNS Servers.", o: "DNS",
    uitleg: "ipconfig /all toont alle instellingen van elke netwerkadapter. Een netwerkadapter is het onderdeel waarmee je computer met een netwerk verbindt, bv. Ethernet of Wi-Fi.\nZoek de adapter die je gebruikt (Ethernet). Daaronder staat de regel DNS Servers met het adres. Na de aanpassing moet daar het adres uit de cursus staan." },
  { v: "Stel de DNS-server van je Ethernet-adapter manueel in voor IPv4.", a: "Rechtsklik op de startknop → Network Connections → Ethernet → DNS server assignment → Edit → Manual → IPv4", o: "DNS", oefening: true,
    uitleg: "Vul de Preferred en Alternate DNS-server uit de cursus in." },
  { v: "Controleer in de CLI op welk IP-adres desktoposisawesome.be gehost wordt.", a: "C:\\> ping desktoposisawesome.be", o: "DNS", oefening: true,
    uitleg: "ping = stuur een testbericht naar een computer. In de uitvoer zie je het IP-adres waarop de naam uitkomt (via DNS).\nVoor het wijzigen van je DNS bestaat de site niet; daarna wel." },
  { v: "Stel de DNS-server van je Ethernet-adapter manueel in voor IPv4. Geef elke stap.", a: "1. Rechtsklik op de startknop.\n2. Klik op Network Connections.\n3. Klik op Ethernet.\n4. Klik bij DNS server assignment op Edit.\n5. Kies Manual in plaats van Automatic (DHCP).\n6. Zet IPv4 aan.\n7. Vul bij Preferred DNS het adres uit de cursus in, en bij Alternate DNS het tweede adres.\n8. Klik op Save.", o: "DNS", oefening: true,
    uitleg: "Network Connections opent in Windows 11 de Instellingen, op de pagina Netwerk en internet.\nEthernet = je bekabelde verbinding.\nDNS server assignment toont welke DNS-server je nu gebruikt; met Edit verander je die.\nNa Save gebruikt je computer meteen de nieuwe DNS-server.\nHet adres van de school-DNS staat in de cursus; ik zet het bewust niet op de kaart." },
  { v: "Doe de DNS-opdracht in de juiste volgorde.", a: "1. Verbind met de VPN.\n2. Surf naar http://desktoposisawesome.be: dat werkt niet.\n3. Pas je DNS aan (Manual, IPv4).\n4. Surf opnieuw: nu werkt het.\n5. Controleer het IP-adres met ping desktoposisawesome.be.", o: "DNS", oefening: true,
    uitleg: "Eerst VPN: zonder VPN is de DNS-server van de school niet bereikbaar.\nEerst surfen zonder aanpassing: zo zie je dat de naam niet werkt.\nDan pas je de DNS aan en surf je opnieuw: nu werkt het. Zo zie je zelf dat het aan de DNS-server lag.\nping toont het IP-adres waarop de naam nu uitkomt." },
  { v: "Controleer in de CLI welke DNS-server je adapter nu gebruikt.", a: "C:\\> ipconfig /all", o: "DNS", oefening: true,
    uitleg: "Zoek in de uitvoer bij je adapter (Ethernet) de regel DNS Servers.\nZo controleer je of je aanpassing gelukt is: daar moet het adres uit de cursus staan, niet meer dat van je router." },
  { v: "Zet je DNS terug zoals hij was.", a: "Dezelfde weg: rechtsklik op de startknop, Network Connections, Ethernet, bij DNS server assignment op Edit. Kies Automatic (DHCP) en klik op Save.", o: "DNS", oefening: true, extra: true,
    uitleg: "Automatic (DHCP) = je computer krijgt de DNS-server weer van het netwerk, zoals voor de opdracht. Zo werkt je internet weer zonder VPN." },
  { v: "Je zit op wifi in plaats van Ethernet. Waar pas je dan de DNS aan?", a: "Network Connections, Wi-Fi, de eigenschappen van je wifinetwerk, en daar bij DNS server assignment op Edit.", o: "DNS", oefening: true, extra: true,
    uitleg: "De DNS-instelling hoort bij één netwerkadapter. Pas je ze aan bij Ethernet terwijl je via wifi verbonden bent, dan verandert er niets. Je moet ze aanpassen bij de adapter die je echt gebruikt." },
  // ===== Task Manager: Processes =====
  { v: "Task Manager", a: "• Openen met Ctrl+Shift+Esc (zie werkcollege 1).\n• Om te zien waarom je pc traag is, of om meer in detail te kijken. Ook leken kunnen er basistaken mee doen.\n• Tabbladen: Processes, Performance, Startup apps, Users, Details en Services.", o: "Task Manager: Processes", wit: true,
    uitleg: "De Task Manager (Taakbeheer) is het venster dat toont wat er nu op je pc draait en hoeveel van de pc elk programma gebruikt.\n\nCtrl+Shift+Esc opent hem rechtstreeks. Ook mogelijk: rechtsklik op de startknop en kies Task Manager.\n\nJe gebruikt hem bv. als je pc traag is: je ziet welk programma veel processorkracht of geheugen gebruikt, en je kan het afsluiten. Ook iemand zonder veel kennis kan er basistaken mee doen, bv. een vastgelopen programma sluiten.\n\nHij heeft verschillende tabbladen; elk tabblad krijgt hieronder zijn eigen kaarten." },
  { v: "Task Manager: Processes", a: "• Een lijst van alle draaiende processen, normaal in 3 delen: Apps, Background processes en Windows Processes (op de VM anders).\n• In één oogopslag de load op CPU, geheugen, schijf en netwerk.\n• Onbekend of verdacht proces (mogelijk virus)? Rechtsklik → Search online.\n• Je kan ook een dump file van een proces maken.", o: "Task Manager: Processes", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_taakbeheer_processes.jpg",
    uitleg: "Een proces = een programma dat op dit moment draait. Eén programma kan uit meerdere processen bestaan (bv. een browser met één proces per tabblad).\n\nDe 3 delen:\n• Apps: programma's met een venster dat je ziet, bv. Word of je browser.\n• Background processes: programma's die op de achtergrond draaien zonder venster, bv. een updateprogramma.\n• Windows processes: onderdelen van Windows zelf.\n\nLoad = hoeveel van de CPU (processor), het geheugen (RAM), de schijf en het netwerk een proces gebruikt, in kolommen naast elkaar.\n\nSearch online: zoekt de naam van het proces op het internet. Zo kan je nagaan of het een normaal programma is of mogelijk een virus.\n\nDump file = een momentopname van het geheugen van het proces, opgeslagen in een bestand. Ontwikkelaars gebruiken dat om te onderzoeken waarom een programma vastloopt." },
  { v: "Open de Task Manager.", a: "  Ctrl+Shift+Esc", o: "Task Manager: Processes", oefening: true,
    uitleg: "Ctrl+Shift+Esc = de drie toetsen Ctrl, Shift en Escape tegelijk indrukken. Dat opent de Task Manager rechtstreeks.\n\nAndere manieren: rechtsklik op de startknop en kies Task Manager, of Ctrl+Alt+Delete en dan Task Manager." },
  { v: "Welke tabbladen heeft de Task Manager?", a: "Processes, Performance, Startup apps, Users, Details en Services.", o: "Task Manager: Processes",
    uitleg: "Elk tabblad toont iets anders:\n• Processes: welke programma's nu draaien en hoeveel ze gebruiken.\n• Performance: grafieken van het totale gebruik van CPU, geheugen, schijf en netwerk.\n• Startup apps: programma's die automatisch starten als Windows opstart.\n• Users: welke gebruikers aangemeld zijn en hoeveel ze gebruiken.\n• Details: dezelfde processen, maar met meer technische info (bv. de prioriteit).\n• Services: programma's die op de achtergrond draaien zonder venster, bv. Windows Update." },
  { v: "In welke 3 delen is Processes normaal verdeeld?", a: "Apps, Background processes en Windows Processes.", o: "Task Manager: Processes",
    uitleg: "• Apps: programma's met een venster dat je ziet en zelf geopend hebt, bv. Word of je browser.\n• Background processes: programma's die op de achtergrond draaien zonder venster, bv. een updateprogramma of OneDrive.\n• Windows processes: onderdelen van Windows zelf, die Windows nodig heeft om te werken.\n\nDe cursus zegt dat het op de VM er anders uitziet; daar kan de indeling verschillen." },
  { v: "Wat zie je in één oogopslag in Processes?", a: "De load die elk proces plaatst op de CPU, het geheugen, de schijf en het netwerk.", o: "Task Manager: Processes",
    uitleg: "Load = hoeveel een proces op dit moment vraagt van:\n• de CPU (de processor, die de berekeningen doet), in %;\n• het geheugen (RAM), in MB;\n• de schijf: hoeveel het leest en schrijft, in MB per seconde;\n• het netwerk: hoeveel het verstuurt en ontvangt, in Mbps.\n\nZo zie je meteen welk proces je pc traag maakt: het proces met de hoogste waarden." },
  { v: "Wat doe je met een proces dat je niet kent of niet vertrouwt?", a: "Rechtsklik → Search online, om op te zoeken wat het doet.", o: "Task Manager: Processes",
    uitleg: "Een proces dat je niet kent, kan een normaal onderdeel van Windows of van een programma zijn, maar ook een virus.\n\nRechtsklik op het proces en kies Search online: Windows zoekt de naam van het proces op het internet. Zo lees je wat het is en of het te vertrouwen is.\n\nIs het verdacht, dan kan je het afsluiten (End task) en je pc laten scannen met een antivirusprogramma." },
  { v: "Wat kan je nog maken van een proces in Processes?", a: "Een dump file.", o: "Task Manager: Processes",
    uitleg: "Een dump file is een momentopname van het geheugen van een proces: alles wat dat proces op dat moment in het RAM had staan, opgeslagen in een bestand (.dmp).\n\nJe maakt hem via rechtsklik op het proces en Create dump file.\n\nWaarvoor: ontwikkelaars en technici openen dat bestand om te onderzoeken waarom een programma vastloopt of crasht." },
  // ===== Task Manager: Performance =====
  { v: "Task Manager: Performance (CPU)", a: "• Diagrammen die het systeem voorstellen, met nuttige info.\n• CPU: het huidige processorgebruik. Bijna 100% = processor-intensieve programma's (bv. ingewikkelde berekeningen).\n• Reageert je pc niet meer goed? Kijk of de processor een tijdsintensieve taak uitvoert.\n• Gecrashte programma's kunnen de processor bijna 100% bezighouden zonder iets te doen. Het verbruik per programma zie je in Processes; zo'n proces sluit je best af.\n\nOpdracht: vul de kloksnelheid, het aantal processen en het aantal threads in.", o: "Task Manager: Performance", wit: true,
    uitleg: "Performance toont grafieken van het totale gebruik van je pc, voor alle programma's samen.\n\nCPU = de processor: het onderdeel dat de berekeningen doet. De grafiek toont welk percentage van zijn capaciteit hij nu gebruikt.\n\nBijna 100% betekent dat de processor volledig bezig is. Andere programma's moeten dan wachten, en je pc reageert traag.\n\nEen gecrasht (vastgelopen) programma kan in een lus blijven draaien en zo de processor bezig houden zonder iets nuttigs te doen. In Processes zie je welk programma het is, en daar sluit je het af.\n\nBegrippen voor de opdracht:\n• Kloksnelheid (Speed): hoeveel rekenstappen de processor per seconde doet, in GHz (1 GHz = 1 miljard per seconde).\n• Processes: het aantal programma's dat nu draait.\n• Threads: een thread is een deel van een proces dat afzonderlijk werk kan doen. Eén proces heeft vaak meerdere threads, dus er zijn veel meer threads dan processen." },
  { v: "Task Manager: Performance (Memory)", a: "• Memory: hoeveel RAM-geheugen er gebruikt wordt.\n• Benadert Available 0 MB, dan wordt de pc merkbaar trager: Windows schrijft delen van het RAM naar de harde schijf. Dat heet virtueel geheugen (virtual memory).\n• Committed: hoeveel virtueel geheugen er gebruikt wordt. Vaak geen geheugen over? Installeer extra RAM.\n• Het virtuele geheugen staat in pagefile.sys, meestal op C:\\ (verborgen systeembestand).\n• Cached Memory: hoeveel geheugen de systeemprocessen gebruiken.\n• Paged Pool: het virtuele geheugen dat de kernel gebruikt; Non-paged Pool: het effectieve geheugen dat de kernel nu gebruikt.", o: "Task Manager: Performance", wit: true,
    uitleg: "Memory = het werkgeheugen (RAM): het snelle geheugen waarin de programma's staan die nu draaien.\n\nAvailable = hoeveel RAM er nog vrij is. Als dat bijna 0 is, past niet alles meer in het RAM. Windows zet dan delen die even niet gebruikt worden op de harde schijf, en haalt ze terug als ze weer nodig zijn. Dat heet virtueel geheugen. Een schijf is veel trager dan RAM, daarom wordt je pc dan merkbaar trager.\n\npagefile.sys = het bestand op de schijf waarin Windows dat virtuele geheugen bewaart, meestal op C:\\. Het is verborgen omdat het een systeembestand is.\n\nCommitted = hoeveel geheugen de programma's samen gevraagd hebben, RAM en virtueel geheugen samen. Is dat vaak hoger dan je RAM, dan is extra RAM de oplossing.\n\nCached Memory, Paged Pool en Non-paged Pool: zie de zwarte kaart daarover." },
  { v: "Task Manager: Performance (Disk)", a: "De activiteit van je logische schijven. Bij het kopiëren van een groot bestand gaan de waarden omhoog; duurt het te lang, kijk naar de snelheid.", o: "Task Manager: Performance", wit: true,
    uitleg: "Disk toont hoeveel je schijf nu bezig is met lezen en schrijven.\n\nLogische schijf = een schijf zoals Windows ze toont, met een letter (C:, D:). Eén fysieke schijf kan uit meerdere logische schijven bestaan (partities).\n\nBij het kopiëren van een groot bestand stijgt de activiteit, en je ziet de snelheid in MB per seconde. Duurt het kopiëren veel te lang, dan toont die snelheid of de schijf traag is." },
  { v: "Task Manager: Performance (Ethernet)", a: "Het IP-adres van elke adapter en het binnenkomende en uitgaande verkeer. Via RDP is Sent nooit 0; Received gaat omhoog als je de muis beweegt (de cursorpositie wordt doorgestuurd). Meer: rechtsklik → View network details.", o: "Task Manager: Performance", wit: true,
    uitleg: "Ethernet = je bekabelde netwerkverbinding (op de VM: de virtuele netwerkkaart).\n\nJe ziet het IP-adres van elke adapter (netwerkkaart) en twee waarden:\n• Sent = wat je pc verstuurt;\n• Received = wat je pc ontvangt.\n\nWaarom Sent via RDP nooit 0 is: met Remote Desktop werk je op een VM op afstand. De VM stuurt het beeld van zijn scherm voortdurend naar jouw pc, dus hij verstuurt altijd iets.\n\nWaarom Received stijgt als je de muis beweegt: jouw pc stuurt elke beweging van de muis naar de VM, zodat de cursor daar meebeweegt.\n\nView network details (rechtsklik) toont nog meer gegevens over de verbinding." },
  { v: "Resource Monitor", a: "Via de 3 puntjes rechtsboven in Performance: nog meer detail per proces, bv. het netwerkverkeer en met welk extern IP-adres het verbonden is. Telt vanaf het moment dat je kijkt.\n\nOpdracht: open programma's tot je over het fysieke geheugen (Total) gaat: de pc schrijft nu processen naar de schijf (pages).", o: "Task Manager: Performance", wit: true,
    uitleg: "De Resource Monitor (Broncontrole) toont nog meer detail dan de Task Manager. Je opent hem via de 3 puntjes rechtsboven in Performance.\n\nVoorbeeld: per proces zie je het netwerkverkeer en met welk extern IP-adres het verbonden is, dus met welke server op het internet het praat.\n\nDe metingen beginnen pas te tellen op het moment dat je de Resource Monitor opent.\n\nDe opdracht: open zoveel programma's tot je meer geheugen gebruikt dan er RAM is (Total). Windows begint dan delen van het geheugen naar de schijf te schrijven (pages): het virtuele geheugen in pagefile.sys. Dat zie je aan de stijgende schijfactiviteit." },
  { v: "Good to know: Performance (niet te kennen)", a: "• Verklaar waarom de schijfactiviteit stijgt wanneer het geheugen dreigt vol te zitten.\n• Gebruik Run (Win+R) met dxdiag en bekijk de grootte van de pagefile.\n• App History: de gebruikte resources van elke Windows Store App, om te zien welke app je pc trager maakt.", o: "Task Manager: Performance", extra: true, nietTeKennen: true,
    uitleg: "Good to know: niet te kennen leerstof.\n\nWaarom stijgt de schijfactiviteit als het geheugen bijna vol zit? Windows schrijft dan delen van het RAM naar de schijf (pagefile.sys) en leest ze terug wanneer ze weer nodig zijn. Dat lezen en schrijven zie je als schijfactiviteit.\n\nRun (Windows + R) opent een klein venster waarin je de naam van een programma typt. dxdiag is het DirectX-diagnoseprogramma: het toont o.a. info over je systeem en de grootte van de pagefile.\n\nApp History: toont hoeveel processortijd en netwerk elke app uit de Windows Store gebruikt heeft, zodat je ziet welke app je pc trager maakt." },
  { v: "Wat toont CPU in Performance, en wat betekent bijna 100%?", a: "Het huidige processorgebruik. Bijna 100% = er draaien processor-intensieve programma's (bv. ingewikkelde berekeningen).", o: "Task Manager: Performance",
    uitleg: "CPU = de processor: het onderdeel dat alle berekeningen doet. Performance toont welk percentage van zijn capaciteit hij nu gebruikt.\n\nBijna 100% = de processor is volledig bezig. Dat gebeurt bij programma's die veel moeten rekenen, bv. video bewerken, een spel of ingewikkelde berekeningen.\n\nAndere programma's moeten dan wachten op hun beurt, en je pc reageert traag. Reageert je pc niet goed meer, kijk dan hier of de processor een zware taak uitvoert." },
  { v: "Wat kan een gecrasht programma doen met de CPU, en wat doe je dan?", a: "Het kan de processor bijna 100% bezighouden zonder iets te doen. Bekijk het in Processes en sluit het af.", o: "Task Manager: Performance",
    uitleg: "Een gecrasht programma = een programma dat vastgelopen is. Soms blijft het in een lus dezelfde stap herhalen: het doet niets nuttigs, maar vraagt wel voortdurend de processor. De CPU staat dan op bijna 100%.\n\nIn Processes zie je per programma hoeveel CPU het gebruikt. Zo vind je het programma dat de processor bezet houdt.\n\nAfsluiten: rechtsklik op het programma en kies End task." },
  { v: "Zoek de kloksnelheid, het aantal processen en het aantal threads.", a: "Task Manager (Ctrl+Shift+Esc) → Performance → CPU", o: "Task Manager: Performance", oefening: true,
    uitleg: "Stap voor stap:\n1. Open de Task Manager met Ctrl+Shift+Esc.\n2. Kies het tabblad Performance.\n3. Klik links op CPU.\n4. Onderaan staan Speed (kloksnelheid), Processes en Threads.\n\nKloksnelheid = hoeveel rekenstappen de processor per seconde doet, in GHz (1 GHz = 1 miljard stappen per seconde).\nProcesses = het aantal programma's dat nu draait.\nThreads = een thread is een deel van een proces dat afzonderlijk werk doet. Eén proces heeft vaak meerdere threads, dus dit getal is veel groter dan het aantal processen." },
  { v: "Wat gebeurt er als Available bij Memory 0 MB benadert?", a: "De pc wordt merkbaar trager: Windows schrijft delen van het RAM naar de harde schijf (virtueel geheugen).", o: "Task Manager: Performance",
    uitleg: "Available = hoeveel RAM (werkgeheugen) er nog vrij is.\n\nIs het RAM vol, dan kan Windows niet alles meer in het RAM houden. Het zet delen die even niet gebruikt worden op de harde schijf, en haalt ze terug als ze weer nodig zijn. Dat heet virtueel geheugen.\n\nEen schijf is veel trager dan RAM. Daarom moet de pc vaak wachten tot de gegevens van de schijf geladen zijn: hij wordt merkbaar trager." },
  { v: "Wat is virtueel geheugen, en in welk bestand staat het?", a: "Geheugen op de harde schijf dat dient als tijdelijke opslag voor wat niet in het RAM past. Het staat in pagefile.sys, meestal op C:\\ (verborgen).", o: "Task Manager: Performance",
    uitleg: "Het RAM (werkgeheugen) is snel, maar beperkt. Als programma's samen meer geheugen nodig hebben dan er RAM is, gebruikt Windows een deel van de harde schijf als extra geheugen: het virtueel geheugen.\n\nWindows verplaatst stukken geheugen die even niet gebruikt worden (pages) van het RAM naar de schijf, en terug wanneer ze nodig zijn.\n\nDat gebeurt in het bestand pagefile.sys, meestal op C:\\. Je ziet het niet standaard, omdat het een verborgen systeembestand is." },
  { v: "Wat toont Committed, en wat doe je als een pc vaak geen geheugen over heeft?", a: "Hoeveel virtueel geheugen er gebruikt wordt. Installeer dan best extra RAM.", o: "Task Manager: Performance",
    uitleg: "Committed = hoeveel geheugen alle programma's samen gevraagd hebben, in het RAM en in het virtueel geheugen (pagefile.sys) samen. Je ziet twee getallen, bv. 6/12 GB: hoeveel er gevraagd is, en het maximum (RAM + pagefile).\n\nIs er vaak geen geheugen meer over, dan moet Windows voortdurend geheugen naar de trage schijf verplaatsen, en wordt de pc traag. Extra RAM lost dat op: dan past meer in het snelle geheugen." },
  { v: "Wat zijn Cached Memory, Paged Pool en Non-paged Pool?", a: "Cached: het geheugen dat de systeemprocessen gebruiken.\nPaged Pool: het virtuele geheugen van de kernel.\nNon-paged Pool: het effectieve geheugen dat de kernel nu gebruikt.", o: "Task Manager: Performance",
    uitleg: "Dit gaat over geheugen dat Windows zelf gebruikt. De kernel is het hart van Windows: het deel dat het geheugen, de processor en de hardware beheert.\n\n• Cached: de cursus zegt het geheugen dat de systeemprocessen gebruiken. Windows gebruikt het om gegevens van de schijf bij te houden die mogelijk nog eens nodig zijn, zodat ze sneller terug te lezen zijn.\n• Paged Pool: geheugen van de kernel dat, als het nodig is, naar de schijf (pagefile.sys) verplaatst mag worden.\n• Non-paged Pool: geheugen van de kernel dat altijd in het RAM moet blijven, omdat de kernel er op elk moment snel aan moet kunnen.\n\n\"Paged\" komt van page: een stuk geheugen dat naar de schijf geschreven kan worden." },
  { v: "Wat toont Disk in Performance?", a: "De activiteit van je logische schijven, bv. tijdens het kopiëren van een groot bestand. De snelheid geeft een eerste aanwijzing of er iets mis is.", o: "Task Manager: Performance",
    uitleg: "Disk toont hoeveel je schijven nu bezig zijn met lezen en schrijven.\n\nLogische schijf = een schijf zoals Windows ze toont, met een letter (C:, D:).\n\nKopieer je een groot bestand, dan stijgt de activiteit en zie je de snelheid in MB per seconde. Duurt het kopiëren veel te lang, dan is die snelheid een eerste aanwijzing: is ze veel lager dan normaal, dan is de schijf misschien traag of defect." },
  { v: "Waarom is Sent bij Ethernet nooit 0, en wanneer stijgt Received?", a: "Via Remote Desktop wordt altijd beeld verstuurd. Received stijgt als je de muis beweegt: de cursorpositie wordt doorgestuurd.", o: "Task Manager: Performance",
    uitleg: "Je werkt op de VM via Remote Desktop (RDP): je ziet het scherm van de VM op je eigen pc.\n\nSent = wat de VM verstuurt. De VM stuurt het beeld van zijn scherm voortdurend naar jouw pc, zodat je ziet wat er gebeurt. Daarom is Sent nooit 0.\n\nReceived = wat de VM ontvangt. Beweeg je de muis, dan stuurt jouw pc de positie van de muis naar de VM, zodat de cursor daar meebeweegt. Daarom stijgt Received." },
  { v: "Wat kan de Resource Monitor meer, en hoe open je hem?", a: "Via de 3 puntjes rechtsboven. Meer detail per proces, bv. het netwerkverkeer en met welk extern IP-adres het verbonden is, gemeten vanaf het moment dat je kijkt.", o: "Task Manager: Performance",
    uitleg: "De Resource Monitor (Broncontrole) is een apart venster met meer detail dan de Task Manager. Je opent hem via de 3 puntjes rechtsboven in het tabblad Performance.\n\nWat hij meer toont, per proces:\n• hoeveel netwerkverkeer het verstuurt en ontvangt;\n• met welk extern IP-adres het verbonden is, dus met welke server op het internet het praat.\n\nZo vind je bv. een programma dat zonder dat je het weet data verstuurt.\n\nDe metingen beginnen pas op het moment dat je het venster opent; wat daarvoor gebeurde, zie je niet." },
  { v: "Open programma's tot je over het fysieke geheugen gaat, en bekijk wat er gebeurt.", a: "Task Manager → Performance → Memory: volg In use tegenover Total", o: "Task Manager: Performance", oefening: true,
    uitleg: "Daarna schrijft de pc regelmatig processen naar de schijf (pages): de schijfactiviteit stijgt." },
  { v: "Bekijk de grootte van de pagefile met dxdiag.", a: "  Win+R\n  dxdiag", o: "Task Manager: Performance", extra: true, nietTeKennen: true,
    uitleg: "Win+R = open Run.\ndxdiag = start de DirectX-diagnose, waarin je o.a. de grootte van de pagefile ziet.\nGood to know: niet te kennen leerstof." },
  // ===== Task Manager: Startup apps, Users, Details en Services =====
  { v: "Task Manager: Startup apps", a: "Taken die automatisch starten bij het opstarten. Uitzetten is makkelijk geworden; je ziet ook hoeveel vertraging ze veroorzaken.", o: "Task Manager: Startup apps, Users, Details en Services", wit: true,
    uitleg: "Startup apps = programma's die automatisch starten als Windows opstart, bv. OneDrive, Teams of een updateprogramma.\n\nHoe meer programma's mee opstarten, hoe langer het duurt voor je pc klaar is. De Task Manager toont per programma de Startup impact: hoeveel vertraging het geeft (Low, Medium, High).\n\nUitzetten: rechtsklik op het programma en kies Disable. Het programma blijft geïnstalleerd en je kan het zelf nog starten; het start alleen niet meer automatisch mee." },
  { v: "Task Manager: Users", a: "Per gebruiker hoeveel processorkracht, geheugen, schijf en netwerk hij gebruikt. Bv. een gebruiker die vergrendelt in plaats van af te melden, laat processen draaien. Met genoeg rechten: rechtsklik → Sign Off.\n\nOpdracht: maak een lokaal useraccount en laat een medestudent via RDP op je VM verbinden: beide sessies staan onder Users.", o: "Task Manager: Startup apps, Users, Details en Services", wit: true,
    uitleg: "Users toont welke gebruikers op dit moment aangemeld zijn op de pc, en hoeveel elk van hen gebruikt: processor (CPU), geheugen, schijf en netwerk.\n\nVergrendelen (Windows + L) is niet hetzelfde als afmelden: bij vergrendelen blijven al je programma's open en blijven ze geheugen en processor gebruiken. Een andere gebruiker die vergrendelt in plaats van zich af te melden, maakt de pc dus trager voor jou.\n\nAls beheerder kan je zo'n gebruiker afmelden: rechtsklik en Sign Off. Zijn programma's worden dan afgesloten.\n\nDe opdracht: maak een lokaal useraccount en laat een medestudent met dat account via RDP op jouw VM inloggen. Dan zie je onder Users twee sessies: die van jou en die van de medestudent." },
  { v: "Task Manager: Details", a: "Info per proces; je kan o.a. de prioriteit wijzigen. Windows is priority based: een proces met een hogere prioriteit komt vaker en langer aan de beurt.", o: "Task Manager: Startup apps, Users, Details en Services", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_details_prioriteit.jpg",
    uitleg: "Good to know: elk proces heeft, zoals in Linux, een Process ID (PID). In CMD toon je de processen met tasklist en sluit je ze af met taskkill." },
  { v: "Task Manager: Services", a: "Services opstarten, afsluiten of herstarten. Meer? Rechtsklik → Open Services.", o: "Task Manager: Startup apps, Users, Details en Services", wit: true,
    uitleg: "Een service is een programma dat op de achtergrond draait, zonder venster, vaak al vanaf het opstarten. Bv. Windows Update, de printerwachtrij (Print Spooler) of de tijdsynchronisatie.\n\nIn de Task Manager kan je een service:\n• opstarten (Start);\n• afsluiten (Stop);\n• herstarten (Restart): handig als een service niet meer goed werkt.\n\nOpen Services (rechtsklik) opent het aparte venster Services, met meer mogelijkheden, bv. instellen of een service automatisch start." },
  { v: "Wat zijn Startup apps, en wat toont de Task Manager erover?", a: "Taken die automatisch starten bij het opstarten van het OS. Je kan ze makkelijk uitzetten en ziet hoeveel vertraging ze veroorzaken.", o: "Task Manager: Startup apps, Users, Details en Services",
    uitleg: "Startup apps = programma's die automatisch starten zodra Windows (het OS = operating system, het besturingssysteem) opstart, bv. OneDrive of Teams.\n\nElk programma dat mee opstart, maakt het opstarten trager en gebruikt daarna geheugen. De Task Manager toont per programma de Startup impact: hoeveel vertraging het veroorzaakt.\n\nUitzetten: rechtsklik en Disable. Het programma blijft geïnstalleerd; het start alleen niet meer automatisch." },
  { v: "Wat zie je in het tabblad Users, en wat kan je er doen?", a: "Per gebruiker de processorkracht, het geheugen, de schijf en het netwerk die hij gebruikt. Met genoeg rechten kan je een gebruiker afmelden: rechtsklik → Sign Off.", o: "Task Manager: Startup apps, Users, Details en Services",
    uitleg: "Users toont alle gebruikers die nu aangemeld zijn, ook via Remote Desktop. Per gebruiker zie je hoeveel processor (CPU), geheugen, schijf en netwerk zijn programma's samen gebruiken.\n\nMet genoeg rechten (als beheerder) kan je een andere gebruiker afmelden: rechtsklik en Sign Off. Al zijn programma's worden dan gesloten, en niet-opgeslagen werk gaat verloren." },
  { v: "Waarom kan een vergrendelde sessie van een andere gebruiker je pc traag maken?", a: "Hij laat op de achtergrond allerlei processen draaien, in plaats van zich af te melden.", o: "Task Manager: Startup apps, Users, Details en Services",
    uitleg: "Vergrendelen (Windows + L) en afmelden zijn niet hetzelfde:\n• Vergrendelen: het scherm wordt beveiligd, maar alle programma's van die gebruiker blijven open en draaien verder.\n• Afmelden: de programma's van die gebruiker worden gesloten.\n\nEen vergrendelde sessie blijft dus processor en geheugen gebruiken. Als er meerdere gebruikers op dezelfde pc aangemeld zijn, deelt iedereen dezelfde processor en hetzelfde geheugen. Zo kan de sessie van een ander jouw pc trager maken." },
  { v: "Wat kan je in het tabblad Details wijzigen?", a: "Onder andere de prioriteit van een proces.", o: "Task Manager: Startup apps, Users, Details en Services",
    uitleg: "Details toont dezelfde processen als Processes, maar met meer technische info per proces, bv. het procesnummer (PID) en de prioriteit.\n\nDe prioriteit wijzig je met rechtsklik op het proces en Set priority. Zie de volgende kaarten: wat prioriteit betekent en welke er zijn." },
  { v: "Wat betekent: Windows is priority based?", a: "Een proces met een hogere prioriteit komt vaker en langer aan de beurt dan een proces met een lagere prioriteit.", o: "Task Manager: Startup apps, Users, Details en Services",
    uitleg: "Er draaien veel meer processen dan de processor tegelijk kan uitvoeren. Daarom wisselt Windows voortdurend af: elk proces krijgt kort de processor, dan het volgende.\n\nPriority based betekent: Windows kijkt naar de prioriteit van elk proces om te beslissen wie aan de beurt is. Een proces met een hogere prioriteit krijgt vaker en langer de processor dan een proces met een lagere prioriteit.\n\nZo kan je bv. een belangrijk programma sneller laten werken door het een hogere prioriteit te geven." },
  { v: "Welke prioriteiten kan je een proces geven?", a: "Realtime, High, Above normal, Normal, Below normal en Low.", o: "Task Manager: Startup apps, Users, Details en Services", imgAntwoord: "afbeeldingen/DesktopOS_windows_wc2/w2_details_prioriteit.jpg",
    uitleg: "Van hoog naar laag:\n• Realtime: de hoogste. Het proces gaat zelfs voor op onderdelen van Windows. Gevaarlijk: de pc kan vastlopen, omdat Windows zelf niet meer aan de beurt komt.\n• High\n• Above normal\n• Normal: de standaard voor bijna alle programma's.\n• Below normal\n• Low: komt pas aan de beurt als er weinig anders te doen is.\n\nInstellen: tabblad Details, rechtsklik op het proces en Set priority." },
  { v: "Wat kan je in het tabblad Services, en hoe ga je verder?", a: "Services opstarten, afsluiten of herstarten. Meer: rechtsklik → Open Services.", o: "Task Manager: Startup apps, Users, Details en Services",
    uitleg: "Een service is een programma dat op de achtergrond draait, zonder venster, bv. Windows Update of de printerwachtrij (Print Spooler).\n\nIn het tabblad Services kan je een service opstarten (Start), afsluiten (Stop) of herstarten (Restart).\n\nOpen Services (rechtsklik) opent het aparte venster Services. Daar kan je meer, bv. instellen of een service automatisch, manueel of helemaal niet start." },
  { v: "Toon de processen in CMD en beëindig een onbelangrijk proces.", a: "C:\\> tasklist\nC:\\> taskkill /PID 1234", o: "Task Manager: Startup apps, Users, Details en Services", extra: true, nietTeKennen: true,
    uitleg: "tasklist = toon alle draaiende processen, met hun PID (procesnummer).\ntaskkill /PID 1234 = beëindig het proces met dat PID; vervang 1234 door het PID uit tasklist. Ook kan: taskkill /IM notepad.exe (op naam).\nGood to know: niet te kennen leerstof." },
  // ===== Device Manager =====
  { v: "Device Manager", a: "• Openen: rechtsklik op de startknop → Device Manager.\n• Alle hardware: harde schijven, dvd, keyboard, muis, netwerkadapter, geluidskaart, ... en ook chipsets op het moederbord.\n• Bij problemen met een apparaat kijk je hier eerst. Een softwarefout los je vaak op door de driver te herinstalleren: rechtsklik → Update Driver Software (enkel als administrator).\n• Unknown device: Properties → Details → hardware id. Zo weet je welke hardware het is en welke driver je zoekt.\n• View aanpassen: i.p.v. by type ook by connection.\n\nOpdracht: controleer als admin of de Display Adapter de laatste driver heeft.", o: "Device Manager", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_device_manager.jpg",
    uitleg: "Good to know: ook te openen via Run (Win+R) met devmgmt.msc, zoals de meeste tools. Of met msinfo32 (bv. de IRQ-kanalen)." },
  { v: "Open de Device Manager.", a: "Rechtsklik op de startknop → Device Manager", o: "Device Manager", oefening: true,
    uitleg: "De Device Manager (Apparaatbeheer) is het venster dat alle hardware van je pc toont, met per apparaat de driver.\n\nStap voor stap:\n1. Rechtsklik op de startknop (of Windows + X).\n2. Kies Device Manager.\n\nDriver = een klein programma dat Windows vertelt hoe het met een bepaald apparaat moet praten. Zonder juiste driver werkt het apparaat niet of slecht." },
  { v: "Open de Device Manager via Run.", a: "  Win+R\n  devmgmt.msc", o: "Device Manager", oefening: true, extra: true, nietTeKennen: true,
    uitleg: "Win+R = open Run.\ndevmgmt.msc = de Device Manager.\nGood to know: niet te kennen leerstof." },
  { v: "Wat kan je in de Device Manager bekijken?", a: "Alle hardware: harde schijven, dvd, keyboard, muis, netwerkadapter, geluidskaart, ... en ook chipsets op het moederbord.", o: "Device Manager",
    uitleg: "De Device Manager toont alle hardware van je pc, gegroepeerd per soort: Disk drives (harde schijven), DVD/CD-ROM drives, Keyboards, Mice, Network adapters (netwerkkaart), Sound (geluidskaart), Display adapters (grafische kaart) enzovoort.\n\nOok de chipsets op het moederbord staan erin: de chips die de onderdelen van de pc met elkaar verbinden (zie IT Essentials, chipsets).\n\nWerkt een apparaat niet goed, dan staat er een geel uitroepteken bij." },
  { v: "Hoe los je een probleem met een apparaat op als het om een softwarefout gaat?", a: "De driver herinstalleren: rechtsklik op het apparaat → Update Driver Software (enkel als administrator).", o: "Device Manager",
    uitleg: "Een probleem met een apparaat kan twee oorzaken hebben:\n• hardware: het apparaat zelf is stuk; dan helpt alleen vervangen;\n• software: de driver werkt niet goed. Driver = het programma dat Windows vertelt hoe het met het apparaat moet praten.\n\nBij een softwarefout installeer je de driver opnieuw: rechtsklik op het apparaat en Update Driver Software (in Windows 11: Update driver). Windows zoekt dan een nieuwe of correcte driver.\n\nEnkel als administrator: drivers werken diep in het systeem. Een foute of kwaadaardige driver kan de hele pc laten crashen, daarom mag een gewone gebruiker dat niet." },
  { v: "Hoe kom je te weten welke hardware een unknown device is?", a: "Properties → Details → het hardware id. Zo weet je ook welke drivers je moet zoeken.", o: "Device Manager",
    uitleg: "Unknown device = een apparaat dat Windows niet herkent, omdat er geen driver voor is. Je weet dus niet wat het is.\n\nElk apparaat heeft een hardware id: een code die het apparaat zelf doorgeeft, met o.a. de fabrikant (VEN = vendor) en het model (DEV = device), bv. PCI\\VEN_8086&DEV_15B8.\n\nStap voor stap:\n1. Rechtsklik op het unknown device en kies Properties.\n2. Tabblad Details.\n3. Kies in de lijst Hardware Ids.\n\nMet die code zoek je op het internet welk apparaat het is, en dus welke driver je moet installeren." },
  { v: "Hoe kan je de View van de Device Manager aanpassen?", a: "In plaats van by type, by connection tonen.", o: "Device Manager",
    uitleg: "Standaard toont de Device Manager de hardware by type: gegroepeerd per soort (alle schijven samen, alle netwerkkaarten samen).\n\nVia het menu View kan je kiezen voor by connection: dan zie je hoe de apparaten met elkaar verbonden zijn, bv. welk apparaat aan welke controller of bus op het moederbord hangt.\n\nHandig om te zien langs welke weg een apparaat met de rest van de pc verbonden is." },
  { v: "Controleer als admin of de Display Adapter de laatste driver heeft.", a: "Device Manager → Display adapters → rechtsklik → Update Driver Software", o: "Device Manager", oefening: true,
    uitleg: "Display adapter = de grafische kaart (of de grafische chip): het onderdeel dat het beeld naar je scherm stuurt.\n\nStap voor stap:\n1. Open de Device Manager (rechtsklik op de startknop).\n2. Klap Display adapters open.\n3. Rechtsklik op de grafische kaart en kies Update Driver Software (in Windows 11: Update driver).\n4. Laat Windows automatisch zoeken. Krijg je de melding dat de beste driver al geïnstalleerd is, dan heb je de laatste.\n\nAls admin: drivers aanpassen mag enkel een administrator." },
  { v: "Bekijk de IRQ-kanalen met msinfo32.", a: "  Win+R\n  msinfo32", o: "Device Manager", extra: true, nietTeKennen: true,
    uitleg: "Win+R = open Run.\nmsinfo32 = System Information, met o.a. de IRQ-kanalen.\nGood to know: niet te kennen leerstof." },
  // ===== Microsoft Management Console =====
  { v: "Good to know: Microsoft Management Console (MMC)", a: "• Een raamwerk waarin je plug-ins (snap-ins) laadt om zaken van je computer te configureren.\n• Openen: Start → mmc.exe typen in het zoekveld (de naam moet juist zijn).\n• Plug-ins laden: File → Add/remove Snap-in, bv. Device Manager en Services; kies Local, of een ander toestel (Remote Management).\n• Voor veel zaken heb je adminrechten nodig, maar je kan ook veel info lezen.", o: "Microsoft Management Console", extra: true, nietTeKennen: true,
    uitleg: "Good to know: niet te kennen leerstof.\n\nMMC is een leeg venster (een raamwerk) waarin je zelf beheerstools toevoegt. Zo'n tool heet een snap-in (plug-in), bv. Device Manager, Services of Disk Management.\n\nVoordeel: je zet de tools die je vaak gebruikt samen in één venster. Je kan er ook een andere computer op het netwerk mee beheren (Remote Management) in plaats van je eigen pc (Local).\n\nOpenen: typ mmc.exe in het zoekveld van Start. Snap-ins toevoegen: File, Add/Remove Snap-in." },
  { v: "Open de Microsoft Management Console en laad de snap-ins Device Manager en Services.", a: "Start → mmc.exe\nFile → Add/remove Snap-in → Device Manager en Services → Local", o: "Microsoft Management Console", oefening: true, extra: true, nietTeKennen: true,
    uitleg: "mmc.exe = de Microsoft Management Console: één venster waarin je beheertools (snap-ins) samenzet.\nAdd/remove Snap-in = kies welke tools erin komen.\nGood to know: niet te kennen leerstof." },
  // ===== Disk Management =====
  { v: "Disk Management", a: "• De harde schijf wordt via volumes ter beschikking gesteld.\n• In de Disk Management Tool bekijk en wijzig je de opdeling in partities.\n• In de Verkenner zie je geen partities, wel de inhoud van de volumes.\n• Een volume (bv. C:\\ of D:\\) is een letter gekoppeld aan een partitie, optische drive of extern opslagmedium.\n• C:\\ is meestal de systeemschijf met de belangrijke systeembestanden.", o: "Disk Management", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_disk_management.jpg",
    uitleg: "Partitie = een deel van een fysieke harde schijf. Je kan één schijf opdelen in meerdere partities, die Windows apart behandelt.\n\nVolume = een stuk opslag dat Windows een letter geeft, bv. C:\\ of D:\\. Meestal is dat een partitie, maar het kan ook een dvd-station of een usb-stick zijn.\n\nDisk Management (Schijfbeheer) toont de fysieke schijven en hoe ze in partities verdeeld zijn. Daar kan je partities maken, verkleinen of verwijderen. Openen: rechtsklik op de startknop en Disk Management.\n\nIn de Verkenner zie je alleen de volumes (C:, D:) en wat erin staat, niet hoe de schijf verdeeld is.\n\nC:\\ is meestal de systeemschijf: daar staat Windows zelf, met de systeembestanden die nodig zijn om de pc te laten werken." },
  { v: "Schijf-eigenschappen: tabblad General", a: "Rechtsklik op een schijf → Properties → General: gebruikte en vrije ruimte; bestanden comprimeren om plaats te besparen; een index opbouwen om sneller te zoeken.", o: "Disk Management", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_c_general.jpg",
    uitleg: "Good to know: ook de tabbladen Security (toegangsrechten), Quota (maximale opslag per gebruiker, bv. Rita 200 MB, John 100 MB) en Sharing (delen op het netwerk, enkel admin)." },
  { v: "Schijf-eigenschappen: tabblad Tools", a: "Rechtsklik op een schijf → Properties → Tools: de schijf nakijken op fouten (bv. defecte sectoren) en defragmenteren: verspreide (stukken van) bestanden weer samen plaatsen, zodat ze sneller te openen zijn.", o: "Disk Management", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_c_tools.jpg",
    uitleg: "Je komt hier via rechtsklik op een schijf (in de Verkenner), Properties, tabblad Tools.\n\nNakijken op fouten (Error checking): Windows controleert de schijf op fouten in het bestandssysteem en op defecte sectoren. Een sector is het kleinste stukje van de schijf dat gelezen of geschreven wordt; een defecte sector kan geen data meer bewaren.\n\nDefragmenteren: als je bestanden maakt, wijzigt en wist, komen stukken van één bestand verspreid over de schijf te staan (fragmentatie). Bij een harde schijf (HDD) moet de leeskop dan naar al die plaatsen bewegen, en dat kost tijd. Defragmenteren zet de stukken van elk bestand weer naast elkaar, zodat de kop ze in één beweging leest.\n\nGood to know: zoek op of het slim is om een SSD te defragmenteren (zie de groene kaart daarover)." },
  { v: "Hoe stelt Windows de harde schijf ter beschikking aan gebruikers?", a: "Aan de hand van volumes.", o: "Disk Management",
    uitleg: "Een harde schijf is voor Windows eerst gewoon een fysiek toestel. Om ze bruikbaar te maken:\n1. wordt ze opgedeeld in een of meer partities (stukken van de schijf);\n2. krijgt elke partitie een bestandssysteem (bv. NTFS) en een letter, bv. C:\\.\n\nZo'n stuk met een letter heet een volume. Als gebruiker werk je altijd met volumes: je opent C:\\ of D:\\, niet de fysieke schijf." },
  { v: "Wat doe je met de Disk Management Tool?", a: "De opdeling van je harde schijf in partities bekijken en wijzigen.", o: "Disk Management",
    uitleg: "Partitie = een deel van een fysieke harde schijf. Je kan één schijf opdelen in meerdere partities, bv. één voor Windows en één voor je data.\n\nIn Disk Management (Schijfbeheer) zie je per fysieke schijf welke partities erop staan, hoe groot ze zijn en welk bestandssysteem ze hebben. Je kan er partities maken, verkleinen (Shrink), vergroten (Extend), formatteren en verwijderen.\n\nOpenen: rechtsklik op de startknop en Disk Management." },
  { v: "Wat is een volume?", a: "Een letter (bv. C:\\ of D:\\) die gekoppeld wordt aan een partitie, een optische drive of een extern opslagmedium.", o: "Disk Management",
    uitleg: "Een volume is een stuk opslag dat Windows een letter geeft, zodat je het in de Verkenner kan openen.\n\nDat kan zijn:\n• een partitie op een harde schijf (bv. C:\\);\n• een optische drive: een cd- of dvd-station;\n• een extern opslagmedium: bv. een usb-stick of externe schijf.\n\nPartitie = een deel van een fysieke schijf. Volume = wat Windows er met een letter van toont." },
  { v: "Wat zie je in de Verkenner wel en niet van je schijven?", a: "Niet de fysieke opdeling in partities, wel de inhoud van de volumes.", o: "Disk Management",
    uitleg: "De Verkenner (File Explorer) toont enkel de volumes: de letters zoals C:\\ en D:\\, en wat erin staat.\n\nJe ziet er niet hoe de fysieke schijf verdeeld is. Bv. of C:\\ en D:\\ op dezelfde schijf staan, en welke verborgen partities er nog zijn (bv. een herstelpartitie).\n\nDie fysieke opdeling zie je enkel in Disk Management." },
  { v: "Wat is de C:\\-schijf meestal?", a: "De systeemschijf, met de belangrijke systeembestanden van het besturingssysteem.", o: "Disk Management",
    uitleg: "De systeemschijf is de schijf waarop Windows zelf geïnstalleerd is, meestal C:\\.\n\nDaar staan o.a.:\n• de map Windows met de systeembestanden die nodig zijn om de pc op te starten en te laten werken;\n• de map Program Files met de geïnstalleerde programma's;\n• de map Users met de bestanden van de gebruikers;\n• pagefile.sys, het virtueel geheugen.\n\nWis of verplaats hier geen systeembestanden: dan kan Windows niet meer opstarten." },
  { v: "Wat bevat het tabblad General van een schijf?", a: "De gebruikte en vrije ruimte; de mogelijkheid om te comprimeren; een index om sneller te zoeken.", o: "Disk Management", img: "afbeeldingen/DesktopOS_windows_wc2/w2_c_general.jpg",
    uitleg: "Je komt hier via de Verkenner: rechtsklik op een schijf, Properties, tabblad General.\n\n• Gebruikte en vrije ruimte: hoeveel er op de schijf staat en hoeveel er nog bij past, met een cirkeldiagram.\n• Comprimeren (Compress this drive): bestanden worden kleiner opgeslagen, zodat er meer op de schijf past. Nadeel: de processor moet ze bij elk gebruik uitpakken.\n• Index (Allow files to be indexed): Windows houdt een lijst bij van de bestanden en hun inhoud. Zoeken gaat dan veel sneller, omdat Windows niet de hele schijf hoeft te doorlopen." },
  { v: "Wat bevat het tabblad Tools van een schijf?", a: "Nakijken op fouten (bv. defecte sectoren) en defragmenteren.", o: "Disk Management", img: "afbeeldingen/DesktopOS_windows_wc2/w2_c_tools.jpg",
    uitleg: "Je komt hier via de Verkenner: rechtsklik op een schijf, Properties, tabblad Tools.\n\nNakijken op fouten (Error checking): Windows controleert de schijf op fouten in het bestandssysteem en op defecte sectoren. Een sector is het kleinste stukje van de schijf dat gelezen of geschreven wordt; een defecte sector kan geen data meer bewaren, en Windows gebruikt hem dan niet meer.\n\nDefragmenteren (Optimize): de stukken van verspreide bestanden weer samen zetten, zodat ze sneller te lezen zijn. Zie de kaart over defragmenteren." },
  { v: "Wat is defragmenteren, en waarom helpt het?", a: "Verspreide bestanden (of blokken ervan) weer samen plaatsen. Het grootste tijdsverlies bij het openen zit in verspreide bestanden, dus de pc kan sneller werken.", o: "Disk Management",
    uitleg: "Een bestand wordt op de schijf in blokken bewaard. Als je bestanden maakt, wijzigt en wist, ontstaan er gaten. Een nieuw of groter bestand wordt dan in stukken over die gaten verdeeld: het bestand is gefragmenteerd.\n\nBij een harde schijf (HDD) moet de leeskop voor elk stuk naar een andere plaats bewegen en wachten tot de platter onder hem draait. Dat bewegen is het grootste tijdsverlies bij het openen van een bestand.\n\nDefragmenteren zet de blokken van elk bestand weer naast elkaar. Dan leest de kop het bestand in één beweging, en opent het sneller.\n\nVoor een SSD geldt dit niet: zie de groene kaart over SSD's." },
  { v: "Open de eigenschappen van de C:\\-schijf.", a: "Verkenner → rechtsklik op C:\\ → Properties", o: "Disk Management", oefening: true,
    uitleg: "Stap voor stap:\n1. Open de Verkenner (Windows + E).\n2. Klik links op This PC.\n3. Rechtsklik op de C:\\-schijf (Local Disk C:).\n4. Kies Properties.\n\nJe ziet nu de tabbladen, o.a. General (ruimte, comprimeren, index) en Tools (fouten nakijken, defragmenteren)." },
  { v: "Een SSD defragmenteren?", a: "Op een SSD heeft defragmenteren geen zin: elk blok is even snel bereikbaar, en onnodig schrijven verkort de levensduur. Windows doet bij een SSD in de plaats een 'optimize' (TRIM).", o: "Disk Management", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus.\n\nEen SSD heeft geen bewegende leeskop: hij leest elk blok even snel, waar het ook staat. Verspreide stukken van een bestand maken een SSD dus niet trager, en defragmenteren levert niets op.\n\nBovendien kan elke geheugencel van een SSD maar een beperkt aantal keer beschreven worden. Defragmenteren verplaatst veel data, dus het schrijft veel en verkort de levensduur.\n\nTRIM = Windows vertelt de SSD welke blokken niet meer gebruikt worden (van gewiste bestanden), zodat de SSD ze op voorhand kan leegmaken. Dat houdt het schrijven snel. In Windows heet dat bij een SSD Optimize." },
  // ===== NTFS, FAT en exFAT =====
  { v: "Formatteringstypes in Windows", a: "Sinds Windows NT zijn er twee formatteringstypes: NTFS (New Technology File System) en FAT (File Allocation Table).", o: "NTFS, FAT en exFAT", wit: true,
    uitleg: "Een formatteringstype (bestandssysteem) bepaalt hoe bestanden op een schijf of partitie bewaard en teruggevonden worden: waar elk bestand staat, hoe groot het mag zijn en wie het mag openen.\n\nWindows NT was de versie van Windows (1993) waarop alle huidige versies gebaseerd zijn.\n\n• NTFS (New Technology File System): het moderne bestandssysteem van Windows, met beveiliging.\n• FAT (File Allocation Table): het oudere, eenvoudige bestandssysteem, zonder beveiliging. FAT32 is de meest gebruikte versie ervan.\n\nexFAT (2006) is een nieuwere versie van FAT; zie de zwarte kaarten." },
  { v: "FAT", a: "Geen beveiliging (iedereen opent alles), bestanden max. 4 GB. Voordeel: Linux en macOS werken er zonder problemen mee.", o: "NTFS, FAT en exFAT", wit: true,
    uitleg: "FAT (File Allocation Table) is een oud, eenvoudig bestandssysteem.\n\nGeen beveiliging: FAT houdt niet bij wie eigenaar is van een bestand of wie het mag openen. Iedereen die de schijf gebruikt, kan alles openen.\n\nMax. 4 GB per bestand: FAT32 bewaart de grootte van een bestand in 32 bits. Het grootste getal dat in 32 bits past, is 2^32 bytes = 4 GiB. Een groter bestand (bv. een lange video) past er niet op.\n\nVoordeel: bijna elk systeem kan FAT lezen en schrijven: Windows, Linux, macOS, maar ook fototoestellen en tv's. Daarom staat het vaak op usb-sticks." },
  { v: "exFAT", a: "Uit 2006: lost de grootte-beperking van FAT op. Meer ondersteund dan NTFS, maar sommige oudere systemen hebben er problemen mee. Windows 11 biedt geen exFAT-optie bij formatteren: gebruik externe tools of de CLI.", o: "NTFS, FAT en exFAT", wit: true,
    uitleg: "Good to know: er bestaat een format-commando, maar via diskpart gaat het sneller." },
  { v: "NTFS", a: "Beveiliging op bestandsniveau, compressie, encryptie, ... Gebruikt op alle huidige Windows-computers. Elk bestand en elke map heeft een owner (de maker) en een lijst met rechten voor gebruikers en groepen. Enkel de administrator kan de owner wijzigen.", o: "NTFS, FAT en exFAT", wit: true,
    uitleg: "NTFS (New Technology File System) is het bestandssysteem van alle huidige Windows-computers.\n\n• Beveiliging op bestandsniveau: voor elk bestand en elke map apart stel je in wie het mag lezen, wijzigen of verwijderen.\n• Compressie: bestanden kleiner opslaan, zodat er meer op de schijf past.\n• Encryptie: bestanden versleutelen, zodat alleen jij ze kan lezen.\n\nOwner (eigenaar) = de gebruiker die het bestand gemaakt heeft. De owner kan de rechten van het bestand instellen.\n\nLijst met rechten: per gebruiker of groep staat erin wat die met het bestand mag doen (bv. lezen, schrijven). Groep = een verzameling gebruikers die dezelfde rechten krijgen, bv. Administrators.\n\nEnkel de administrator kan de owner wijzigen; anders zou iedereen zich eigenaar van andermans bestanden kunnen maken." },
  { v: "Opdracht: partitie maken en formatteren. Welke stappen voer je uit?", a: "• Zoek op: wat formatteren betekent, low-level vs. high-level formatting, zero bit fill, Quick Format vs. Full Format.\n• Maak een nieuwe partitie door C:\\ met 5 GB te verkleinen (Shrink Volume).\n• Geef ze de letter E: en formatteer met FAT. Navigeer in de CLI naar de nieuwe schijf.\n• Formatteer opnieuw, nu met exFAT.", o: "NTFS, FAT en exFAT", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_shrink_volume.jpg",
    uitleg: "Formatteren = een bestandssysteem op een partitie zetten (alles erop wordt gewist). Shrink Volume = een bestaande partitie kleiner maken, zodat er vrije ruimte komt voor een nieuwe. FAT en exFAT = bestandssystemen; exFAT kan grotere bestanden aan." },
  { v: "Welke 2 formatteringstypes ondersteunt Windows sinds Windows NT? Voluit?", a: "NTFS (New Technology File System) en FAT (File Allocation Table).", o: "NTFS, FAT en exFAT",
    uitleg: "Een formatteringstype (bestandssysteem) bepaalt hoe bestanden op een schijf bewaard worden: waar elk bestand staat, hoe groot het mag zijn en wie het mag openen.\n\n• NTFS = New Technology File System: het moderne bestandssysteem van Windows, met beveiliging, compressie en encryptie.\n• FAT = File Allocation Table: het oudere, eenvoudige bestandssysteem. De naam komt van de tabel waarin staat welke stukken van de schijf bij welk bestand horen.\n\nWindows NT (1993) is de versie waarop alle huidige versies van Windows gebaseerd zijn." },
  { v: "Wat zijn de nadelen van FAT, en wat is het enige voordeel?", a: "Geen beveiliging (iedereen kan alle bestanden openen) en bestanden van max. 4 GB. Voordeel: Linux en macOS werken er zonder problemen mee.", o: "NTFS, FAT en exFAT",
    uitleg: "Nadelen:\n• Geen beveiliging: FAT houdt niet bij wie eigenaar is of wie een bestand mag openen. Iedereen die de schijf gebruikt, kan alles openen.\n• Max. 4 GB per bestand: FAT32 bewaart de grootte van een bestand in 32 bits, en 2^32 bytes = 4 GiB. Een grotere video past er niet op.\n\nVoordeel: FAT is heel eenvoudig, dus bijna elk systeem kan het lezen en schrijven: Linux, macOS, maar ook fototoestellen en tv's. Daarom gebruik je het om bestanden tussen verschillende systemen uit te wisselen, bv. op een usb-stick." },
  { v: "Waarom kwam exFAT, en wanneer?", a: "In 2006, om de bestandsgroottebeperking van FAT op te lossen.", o: "NTFS, FAT en exFAT",
    uitleg: "exFAT (extended FAT) kwam in 2006.\n\nHet probleem: FAT32 laat geen bestanden groter dan 4 GB toe. Met grotere usb-sticks en lange video's werd dat een probleem.\n\nexFAT bewaart de bestandsgrootte met veel meer bits, zodat bestanden van vele terabytes mogelijk zijn. Het blijft wel eenvoudig, zoals FAT: geen beveiliging per bestand. Daarom wordt het vooral gebruikt op usb-sticks en geheugenkaarten." },
  { v: "Wat is het probleem met exFAT?", a: "Sommige oudere systemen en distro's hebben er problemen mee. En Windows 11 biedt geen exFAT-optie bij formatteren (externe tools of de CLI).", o: "NTFS, FAT en exFAT",
    uitleg: "Distro = een Linux-distributie, bv. Ubuntu of Debian: een versie van Linux met zijn eigen programma's.\n\nexFAT is nieuwer dan FAT. Oudere systemen en sommige Linux-distributies kunnen het niet lezen zonder extra software.\n\nVolgens de cursus biedt Windows 11 bij het formatteren geen exFAT-optie aan. Je hebt dan een extern programma nodig, of de CLI (de opdrachtregel), bv. met het commando format." },
  { v: "Wat biedt NTFS meer dan FAT?", a: "Beveiliging op bestandsniveau, comprimeren, encryptie, ... Daarom gebruiken alle huidige Windows-computers NTFS.", o: "NTFS, FAT en exFAT",
    uitleg: "NTFS (New Technology File System) heeft functies die FAT niet heeft:\n• Beveiliging op bestandsniveau: per bestand en per map stel je in wie het mag lezen, wijzigen of verwijderen. Bij FAT kan iedereen alles openen.\n• Comprimeren: bestanden kleiner opslaan, zodat er meer op de schijf past.\n• Encryptie: bestanden versleutelen, zodat alleen de juiste gebruiker ze kan lezen.\n• Geen grens van 4 GB per bestand.\n\nOmdat een pc meerdere gebruikers heeft en hun bestanden beschermd moeten zijn, gebruiken alle huidige Windows-computers NTFS." },
  { v: "Wie is de owner van een bestand op NTFS, en wie kan hem wijzigen?", a: "Typisch de gebruiker die het bestand gemaakt heeft. Enkel de administrator kan de owner wijzigen.", o: "NTFS, FAT en exFAT",
    uitleg: "Op NTFS heeft elk bestand en elke map een owner (eigenaar): meestal de gebruiker die het gemaakt heeft.\n\nDe owner mag de rechten van zijn bestand instellen: wie het mag lezen, wijzigen of verwijderen.\n\nEnkel de administrator kan de owner wijzigen. Zou elke gebruiker dat kunnen, dan kon iedereen zich eigenaar maken van andermans bestanden en zichzelf alle rechten geven." },
  { v: "Wat bevat elk bestand en elke map op NTFS nog?", a: "Een lijst van gebruikers en groepen met rechten.", o: "NTFS, FAT en exFAT",
    uitleg: "Op NTFS heeft elk bestand en elke map een lijst met rechten (een ACL, access control list).\n\nIn die lijst staat per gebruiker of per groep wat die met het bestand mag doen, bv. lezen, schrijven, wijzigen of verwijderen.\n\nGroep = een verzameling gebruikers die samen dezelfde rechten krijgen, bv. Administrators of Users. Zo moet je de rechten niet voor elke gebruiker apart instellen.\n\nJe ziet die lijst via rechtsklik op een bestand, Properties, tabblad Security." },
  { v: "Maak een nieuwe partitie door de C:\\-schijf met 5 GB te verkleinen.", a: "Disk Management → rechtsklik op C: → Shrink Volume → 5120 MB\nRechtsklik op de vrije ruimte → New Simple Volume", o: "NTFS, FAT en exFAT", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_shrink_volume.jpg",
    uitleg: "Je maakt ruimte vrij op C:\\ en maakt er een nieuwe partitie van.\n\nStap voor stap:\n1. Open Disk Management (rechtsklik op de startknop).\n2. Rechtsklik op C: en kies Shrink Volume (verkleinen).\n3. Vul 5120 in: Windows vraagt het aantal MB, en rekent met 1024. 5 GB = 5 × 1024 = 5120 MB.\n4. Klik op Shrink. Er verschijnt een stuk Unallocated (niet-toegewezen ruimte) van 5 GB.\n5. Rechtsklik op die vrije ruimte en kies New Simple Volume.\n6. Volg de wizard: kies de grootte, een letter (bv. E:) en het bestandssysteem (NTFS), en laat de partitie formatteren.\n\nDaarna zie je de nieuwe schijf E: in de Verkenner." },
  { v: "Navigeer in de CLI naar je nieuwe schijf E: en toon de inhoud.", a: "C:\\> E:\nE:\\> dir", o: "NTFS, FAT en exFAT", oefening: true,
    uitleg: "Stap voor stap:\n1. Typ E: en druk Enter. Je gaat naar het volume E; de prompt wordt E:\\>.\n2. Typ dir en druk Enter. Je ziet de inhoud van de schijf.\n\nIn CMD wissel je van schijf door enkel de letter met een dubbelpunt te typen. cd E:\\ werkt in CMD niet om van schijf te wisselen.\n\nEen nieuwe schijf is leeg: dir toont dan geen bestanden, wel de vrije ruimte." },
  { v: "Formatteer partitie E: opnieuw met exFAT, via diskpart.", a: "C:\\> diskpart\nDISKPART> list disk\nDISKPART> select disk 0\nDISKPART> list partition\nDISKPART> select partition 3\nDISKPART> format fs=exfat", o: "NTFS, FAT en exFAT", oefening: true, imgAntwoord: "afbeeldingen/DesktopOS_windows_wc2/w2_diskpart.jpg",
    uitleg: "diskpart = de tool om schijven en partities te beheren (prompt DISKPART>).\nlist disk / select disk 0 = toon de schijven en kies schijf 0.\nlist partition / select partition 3 = toon de partities en kies je nieuwe partitie (kies je eigen nummer).\nformat fs=exfat = formatteer met het bestandssysteem exFAT.\nEr bestaat ook een format-commando, maar diskpart gaat sneller." },
  { v: "Formatteren, low-level en high-level", a: "Formatteren = een schijf of partitie klaarmaken voor gebruik met een bestandssysteem (NTFS, FAT, ...); de bestaande gegevens worden onbruikbaar.\nLow-level formatting: de fysieke indeling van de schijf in sporen en sectoren (gebeurt in de fabriek).\nHigh-level formatting: het bestandssysteem aanmaken (wat Windows doet).", o: "NTFS, FAT en exFAT", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus.\n\nFormatteren = een schijf of partitie klaarmaken zodat er bestanden op kunnen. Wat er al op stond, is daarna niet meer bereikbaar.\n\n• Low-level formatting: de schijf wordt fysiek ingedeeld in sporen (cirkels op de platter) en sectoren (stukjes van een spoor). Dat gebeurt in de fabriek; als gebruiker doe je dat niet.\n• High-level formatting: er wordt een bestandssysteem op gezet, bv. NTFS: de structuur die bijhoudt welke bestanden waar staan. Dat is wat Windows doet als je formatteert." },
  { v: "Zero fill", a: "Zero (bit) fill: elke sector van de schijf wordt met nullen overschreven, zodat oude data niet meer te herstellen is.", o: "NTFS, FAT en exFAT", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus.\n\nBij gewoon wissen of een snelle formattering verdwijnt enkel de verwijzing naar de bestanden. De data zelf staat nog op de schijf, en met speciale programma's kan je ze vaak terughalen.\n\nZero fill overschrijft elke sector van de schijf met nullen. Daarna is de oude data echt weg. Je doet dit bv. voor je een schijf weggeeft of verkoopt." },
  { v: "Quick Format", a: "Maakt enkel een nieuw, leeg bestandssysteem; snel.", o: "NTFS, FAT en exFAT", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus.\n\nQuick Format maakt enkel een nieuw, leeg bestandssysteem: de lijst die bijhoudt welke bestanden waar staan, wordt leeggemaakt.\n\nDe oude data zelf blijft op de schijf staan, maar is niet meer zichtbaar. Daarom gaat het snel: enkele seconden.\n\nDe schijf wordt niet gecontroleerd op defecte sectoren." },
  { v: "Full Format", a: "Controleert ook de hele schijf op slechte sectoren (en schrijft sinds Vista nullen); traag.", o: "NTFS, FAT en exFAT", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus.\n\nFull Format maakt een nieuw bestandssysteem, zoals Quick Format, maar controleert ook elke sector van de schijf. Defecte sectoren worden gemarkeerd, zodat Windows ze niet meer gebruikt.\n\nSinds Windows Vista schrijft Full Format ook nullen op de hele schijf, zodat de oude data echt weg is.\n\nDaarom duurt het lang: bij een grote schijf soms uren." },
  // ===== Programma's en features =====
  { v: "Programma's en features", a: "• De bovenste optie in het rechtsklikmenu van de startknop: apps verwijderen (Installed apps).\n• Settings → Apps: Advanced app settings, bv. Windows Updates de-installeren (als een update problemen geeft, tot er een bugfix is).\n• System → Optional Features: features aan- en uitzetten; via Related settings → More Windows features.\n• Een feature die je in je 2de jaar nodig hebt: IIS (Internet Information Services).\n\nOpdrachten: installeer en de-installeer een tool uit werkcollege 1; zet IIS aan.", o: "Programma's en features", wit: true,
    uitleg: "Dit gaat over programma's installeren en verwijderen, en onderdelen van Windows aan- of uitzetten.\n\n• Installed apps: de bovenste optie als je rechtsklikt op de startknop. Een lijst van alle geïnstalleerde programma's, waar je ze kan verwijderen.\n• Een Windows Update de-installeren: soms geeft een update problemen. Dan verwijder je ze tijdelijk, tot Microsoft een verbeterde versie (bugfix) uitbrengt.\n• Feature = een onderdeel van Windows dat standaard uit staat en dat je zelf kan aanzetten, bv. IIS.\n• IIS (Internet Information Services) = de webserver van Microsoft: een programma dat websites aanbiedt aan browsers. Je hebt het in je 2de jaar nodig voor webontwikkeling.\n\nOpdrachten: installeer een tool uit werkcollege 1 en verwijder hem weer; zet IIS aan." },
  { v: "Waar verwijder je snel apps?", a: "Via de bovenste optie in het rechtsklikmenu van de startknop (Installed apps).", o: "Programma's en features",
    uitleg: "Stap voor stap:\n1. Rechtsklik op de startknop.\n2. Kies de bovenste optie: Installed apps (Geïnstalleerde apps).\n3. Zoek het programma, klik op de 3 puntjes ernaast en kies Uninstall.\n\nZo verwijder je een programma volledig, ook de bestanden die het overal op je pc gezet heeft. Gewoon de map van het programma wissen is niet genoeg." },
  { v: "Waarom zou je een Windows Update de-installeren, en waar?", a: "Als een update bij bepaalde gebruikers problemen geeft, tot er een bugfix komt. Via Settings → Apps → Advanced app settings.", o: "Programma's en features",
    uitleg: "Een Windows Update verbetert Windows, maar soms geeft een update bij bepaalde gebruikers problemen, bv. een programma of een printer werkt niet meer.\n\nDan de-installeer je de update tijdelijk, tot Microsoft een nieuwe versie uitbrengt die de fout oplost (een bugfix).\n\nDe cursus zegt: via Settings, Apps, Advanced app settings.\nTer info: in Windows 11 vind je het ook via Settings, Windows Update, Update history, Uninstall updates." },
  { v: "Waar zet je Windows-features aan en uit?", a: "System → Optional Features; extra via Related settings → More Windows features.", o: "Programma's en features",
    uitleg: "Een feature is een onderdeel van Windows dat standaard uit staat, omdat niet iedereen het nodig heeft, bv. IIS (een webserver) of Hyper-V (virtuele machines).\n\nStap voor stap:\n1. Open Settings (Windows + I).\n2. Kies System en dan Optional features.\n3. Onderaan, bij Related settings, klik je op More Windows features.\n4. Er opent een venster met een lijst: vink een feature aan om ze aan te zetten, of uit om ze uit te zetten.\n5. Klik op OK; soms moet je de pc herstarten." },
  { v: "Welke feature heb je waarschijnlijk in je 2de jaar nodig?", a: "IIS (Internet Information Services).", o: "Programma's en features",
    uitleg: "IIS = Internet Information Services: de webserver van Microsoft.\n\nEen webserver is een programma dat websites aanbiedt: als een browser een pagina vraagt, stuurt de webserver die pagina terug.\n\nIn je 2de jaar maak je websites en webtoepassingen, en met IIS kan je die op je eigen Windows-pc laten draaien en testen.\n\nIIS staat standaard uit: je zet het aan als Windows-feature." },
  { v: "Zet Internet Information Services aan.", a: "Settings → System → Optional Features → More Windows features → vink Internet Information Services aan", o: "Programma's en features", oefening: true,
    uitleg: "Stap voor stap:\n1. Open Settings (Windows + I).\n2. Kies System en dan Optional features.\n3. Onderaan, bij Related settings, klik je op More Windows features.\n4. Vink Internet Information Services aan.\n5. Klik op OK en wacht tot Windows het geïnstalleerd heeft.\n\nControle: surf in je browser naar http://localhost. Zie je de blauwe welkomstpagina van IIS, dan werkt het.\n\nlocalhost = je eigen computer." },
  { v: "Installeer een tool uit werkcollege 1 en de-installeer ze weer.", a: "C:\\> winget install pakket\nC:\\> winget uninstall pakket", o: "Programma's en features", oefening: true,
    uitleg: "winget install pakket = installeer de tool.\nwinget uninstall pakket = verwijder ze weer.\nOf via Installed apps (rechtsklik op de startknop)." },
  // ===== UAC =====
  { v: "UAC (User Account Control)", a: "• 'Least user' of 'standard user accounts': werken als gewone gebruiker, niet altijd als administrator.\n• Sinds Windows Vista: UAC, om least user te benutten en minder kansen te geven aan spyware en verdachte software.\n• Iedereen, ook een admin, werkt als gewone gebruiker. Pas bij een taak met adminrechten vraagt Windows 'Administrator Credentials':\n– geen lid van administrators: gebruikersnaam + wachtwoord van een admin-account\n– wel lid: enkel toelating\n• Uitschakelen (geen goed idee): Change User Account Control settings op Never notify.\n\nOpdracht: wat is het grote nadeel om als admin al je programma's uit te voeren?", o: "UAC", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_uac.jpg",
    uitleg: "Administrator (admin) = een gebruiker met alle rechten: hij mag programma's installeren, systeeminstellingen wijzigen en aan alle bestanden. Een gewone gebruiker (standard user) mag enkel zijn eigen bestanden en instellingen aanpassen.\n\nLeast user = je werkt gewoon als standard user, en gebruikt adminrechten enkel als het echt nodig is. Een programma dat je start, krijgt dan ook maar de rechten van een gewone gebruiker.\n\nUAC (User Account Control, sinds Windows Vista in 2007) dwingt dat af: zelfs als je admin bent, draaien je programma's eerst met gewone rechten. Wil een programma iets doen waarvoor adminrechten nodig zijn (bv. software installeren), dan verschijnt een venster dat om toestemming vraagt:\n• ben je geen admin: je moet de gebruikersnaam en het wachtwoord van een admin-account invullen;\n• ben je wel admin: je klikt enkel op Yes.\n\nZo kan spyware of een verdacht programma niet ongemerkt adminrechten krijgen: jij ziet het venster en kan weigeren.\n\nUitschakelen (Never notify) is geen goed idee: dan krijgt elk programma van een admin meteen alle rechten, zonder dat je het merkt.\n\nOpdracht: het antwoord staat op de zwarte kaart over het grote nadeel." },
  { v: "Wat is het concept 'least user'?", a: "Je werkt als gewone gebruiker op je systeem en bent niet de hele tijd als administrator ingelogd.", o: "UAC",
    uitleg: "Administrator = een gebruiker met alle rechten op de pc. Gewone gebruiker (standard user) = mag enkel zijn eigen bestanden en instellingen aanpassen.\n\nLeast user betekent: je werkt standaard als gewone gebruiker, met zo weinig rechten als nodig. Adminrechten gebruik je enkel op het moment dat je ze echt nodig hebt, bv. om een programma te installeren.\n\nWaarom: elk programma dat je start, krijgt dezelfde rechten als jij. Ben je gewone gebruiker, dan kan ook een slecht programma maar weinig beschadigen." },
  { v: "Wat is het grote nadeel om als lid van de administrators groep al je programma's uit te voeren?", a: "Elk programma, ook spyware of verdachte software, krijgt dan meteen alle rechten en kan het systeem beschadigen.", o: "UAC",
    uitleg: "Elk programma dat je start, krijgt dezelfde rechten als jij.\n\nWerk je altijd als administrator, dan krijgt elk programma dus alle rechten: het mag systeembestanden wijzigen, zichzelf installeren als service, andere programma's aanpassen en aan de bestanden van alle gebruikers.\n\nOpen je per ongeluk spyware of een virus (bv. via een bijlage of een download), dan kan dat programma meteen alles doen, zonder dat iemand toestemming vraagt. Als gewone gebruiker kan het veel minder beschadigen." },
  { v: "Waarvoor staat UAC, sinds wanneer bestaat het en waarvoor werd het ontworpen?", a: "User Account Control, sinds Windows Vista. Om least user ten volle te benutten en minder kansen te geven aan spyware en verdachte software.", o: "UAC",
    uitleg: "UAC = User Account Control (gebruikersaccountbeheer). Het bestaat sinds Windows Vista (2007).\n\nVoor Vista werkten veel mensen altijd als administrator. Elk programma kreeg dan alle rechten, ook spyware.\n\nUAC is ontworpen om least user ten volle te benutten: iedereen werkt met de rechten van een gewone gebruiker, en Windows vraagt toestemming zodra iets adminrechten nodig heeft. Zo krijgen spyware en verdachte software minder kansen: ze kunnen niet ongemerkt het systeem aanpassen." },
  { v: "Hoe werkt iedereen onder UAC, ook een admin?", a: "Als gewone gebruiker. Pas bij een taak met adminrechten vraagt Windows Administrator Credentials.", o: "UAC",
    uitleg: "Onder UAC draaien alle programma's eerst met de rechten van een gewone gebruiker, ook als je ingelogd bent als admin.\n\nWil je iets doen waarvoor adminrechten nodig zijn, bv. een programma installeren of een systeeminstelling wijzigen, dan wordt het scherm donker en verschijnt het UAC-venster. Windows vraagt dan Administrator Credentials: bewijs dat je de rechten hebt (zie de volgende kaart).\n\nPas na die toestemming krijgt dat ene programma adminrechten." },
  { v: "Wat vraagt UAC aan een gebruiker die geen lid is van de administrators groep? En aan een lid?", a: "Geen lid: een gebruikersnaam en wachtwoord van een account in de administrators groep.\nWel lid: enkel een toelating om door te gaan.", o: "UAC",
    uitleg: "Credentials = de gegevens waarmee je bewijst wie je bent: gebruikersnaam en wachtwoord.\n\n• Geen lid van de Administrators groep: je hebt zelf geen adminrechten. Het UAC-venster vraagt daarom de gebruikersnaam en het wachtwoord van iemand die wel admin is.\n• Wel lid: je hebt de rechten al. Het UAC-venster vraagt enkel of je echt wil doorgaan: je klikt op Yes.\n\nIn beide gevallen moet een mens bewust toestemming geven; een programma kan dat niet zelf." },
  { v: "Schakel UAC uit (geen goed idee).", a: "Change User Account Control settings → Never notify", o: "UAC", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_uac.jpg",
    uitleg: "Stap voor stap:\n1. Typ UAC of Change User Account Control settings in het zoekveld van Start en open het.\n2. Je ziet een schuifbalk met 4 standen.\n3. Schuif hem helemaal naar beneden: Never notify.\n4. Klik op OK en bevestig.\n\nGeen goed idee: programma's van een admin krijgen dan meteen alle rechten, zonder dat Windows iets vraagt. Zet hem na de oefening terug op de standaardstand (de tweede van boven)." },
  // ===== Users toevoegen =====
  { v: "Users toevoegen met lusrmgr", a: "• Kan op verschillende manieren, bv. ook via de Computer Management Tool.\n• Hier via lusrmgr: zoek lusrmgr.msc in de Windows Searchbar.\n• Je ziet alle gebruikers; een pijltje naar beneden = het account is disabled.\n• Onder Groups: groepen om policies (regels) op te leggen of extra opties en rechten te geven.\n\nOpdrachten: maak Jimmy, Joske en Jefke; disable Jimmy; Joske in Administrators; nieuwe groep Noobs met Jefke (location: de lokale pc, niet het domein).", o: "Users toevoegen", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_lusrmgr.jpg",
    uitleg: "Lokale gebruiker = een account dat enkel op deze ene pc bestaat (niet in een domein).\n\nlusrmgr.msc = Local Users and Groups: de tool om lokale gebruikers en groepen te beheren. Typ lusrmgr.msc in het zoekveld van Start.\nTer info: in Windows Home bestaat lusrmgr niet; daar gebruik je Settings, Accounts.\n\nJe ziet twee mappen:\n• Users: alle gebruikers. Een pijltje naar beneden bij een gebruiker = het account is disabled (uitgeschakeld): het bestaat nog, maar niemand kan ermee inloggen.\n• Groups: groepen. Een groep is een verzameling gebruikers die samen dezelfde rechten of regels (policies) krijgen. Bv. wie in de groep Administrators zit, is admin.\n\nLocation bij een nieuwe groep: zoek de gebruiker op deze pc zelf, niet in het domein." },
  { v: "Open de tool om lokale gebruikers te beheren.", a: "Windows Searchbar → lusrmgr.msc", o: "Users toevoegen", oefening: true,
    uitleg: "lusrmgr.msc = Local Users and Groups. Het staat voor local user manager. Met deze tool maak, wijzig en verwijder je lokale gebruikers en groepen: accounts die enkel op deze pc bestaan.\n\n.msc = een snap-in van de Microsoft Management Console (MMC).\n\nStap voor stap: typ lusrmgr.msc in het zoekveld van Start (de Windows Searchbar) en druk Enter. Ook mogelijk via Windows + R.\n\nTer info: in Windows Home bestaat deze tool niet." },
  { v: "Wat betekent een pijltje naar beneden bij een account in lusrmgr?", a: "Het account is disabled.", o: "Users toevoegen", img: "afbeeldingen/DesktopOS_windows_wc2/w2_lusrmgr.jpg",
    uitleg: "Disabled = uitgeschakeld. Het account bestaat nog, met al zijn bestanden en instellingen, maar niemand kan ermee inloggen.\n\nWaarom niet gewoon verwijderen? Bv. als een werknemer tijdelijk weg is, of als je eerst wil nagaan of iemand de bestanden nog nodig heeft. Later kan je het account weer enablen.\n\nZo zet je het: rechtsklik op de gebruiker, Properties, vink Account is disabled aan." },
  { v: "Waarvoor dienen groepen in Windows?", a: "Om policies (regels) te verplichten, en om gebruikers extra opties en rechten op de pc te geven.", o: "Users toevoegen",
    uitleg: "Een groep is een verzameling gebruikers.\n\nIn plaats van elke gebruiker apart rechten te geven, geef je de rechten aan een groep. Iedereen die lid is van die groep, krijgt ze dan.\n\nVoorbeelden:\n• De groep Administrators: wie erin zit, heeft alle rechten op de pc.\n• De groep Users: gewone gebruikers.\n• Een eigen groep, bv. Noobs, waar je strenge regels op zet.\n\nPolicies = regels die Windows oplegt, bv. hoe lang een wachtwoord moet zijn of wat een gebruiker niet mag wijzigen.\n\nVoeg je een nieuwe gebruiker toe aan de groep, dan krijgt hij meteen alle rechten en regels van die groep." },
  { v: "Maak de gebruikers Jimmy, Joske en Jefke, en disable Jimmy.", a: "lusrmgr.msc → Users → rechtsklik → New User (3 keer)\nRechtsklik Jimmy → Properties → Account is disabled", o: "Users toevoegen", oefening: true,
    uitleg: "Stap voor stap:\n1. Open lusrmgr.msc (zoekveld van Start).\n2. Klik op de map Users.\n3. Rechtsklik in de lege ruimte en kies New User.\n4. Vul de gebruikersnaam in (Jimmy) en een wachtwoord, en klik op Create.\n5. Herhaal voor Joske en Jefke.\n6. Rechtsklik op Jimmy en kies Properties.\n7. Vink Account is disabled aan en klik op OK.\n\nJimmy krijgt nu een pijltje naar beneden: het account bestaat, maar niemand kan ermee inloggen." },
  { v: "Maak Joske lid van de Administrators groep.", a: "lusrmgr.msc → Groups → Administrators → Add → Joske", o: "Users toevoegen", oefening: true,
    uitleg: "Wie lid is van de groep Administrators, krijgt alle adminrechten op de pc.\n\nStap voor stap:\n1. Open lusrmgr.msc.\n2. Klik op de map Groups.\n3. Dubbelklik op Administrators.\n4. Klik op Add.\n5. Typ Joske en klik op Check Names: de naam wordt onderlijnd als Windows de gebruiker vindt.\n6. Klik op OK.\n\nJoske is nu administrator." },
  { v: "Maak een groep Noobs met Jefke erin, met als location de lokale pc.", a: "lusrmgr.msc → Groups → rechtsklik → New Group → Noobs → Add → Locations: de lokale pc → Jefke", o: "Users toevoegen", oefening: true,
    uitleg: "Stap voor stap:\n1. Open lusrmgr.msc.\n2. Rechtsklik op de map Groups en kies New Group.\n3. Typ de naam Noobs.\n4. Klik op Add.\n5. Klik op Locations en kies de lokale pc (de naam van je VM), niet het domein.\n6. Typ Jefke, klik op Check Names en dan op OK.\n7. Klik op Create.\n\nLocation = waar Windows de gebruiker zoekt. Jefke is een lokale gebruiker: hij bestaat enkel op deze pc, dus in het domein zou Windows hem niet vinden." },
  // ===== User profiles =====
  { v: "User profiles: wat krijgt elke gebruiker?", a: "Elke gebruiker krijgt een Registry Hive en profielfolders, onder C:/Users.\n• Bekend: Documents, Downloads, Desktop.\n• Minder bekend: AppData.", o: "User profiles", wit: true,
    uitleg: "Een user profile is alles wat bij één gebruiker hoort: zijn mappen en zijn persoonlijke instellingen.\n\nRegistry Hive = het deel van het register met de instellingen van die gebruiker, bv. zijn achtergrond en de instellingen van zijn programma's. Het register is de database met alle instellingen van Windows (zie Het register). Het bestand heet NTUSER.DAT en staat in de profielmap.\n\nProfielfolders: elke gebruiker krijgt een eigen map in C:\\Users, bv. C:\\Users\\Jefke, met daarin:\n• bekend: Documents, Downloads, Desktop (de bestanden op je bureaublad);\n• minder bekend: AppData (verborgen; zie de kaart AppData).\n\nZo blijven de bestanden en instellingen van elke gebruiker apart." },
  { v: "AppData", a: "Een verborgen map in je profiel (vink hidden items aan om ze te zien). Applicaties bewaren er data en settings per gebruiker.\n\nSnel ernaartoe: typ %APPDATA% in de navigatiebalk van de Verkenner (een systeemvariabele).", o: "User profiles", wit: true,
    uitleg: "AppData = application data. Programma's bewaren er hun gegevens en instellingen per gebruiker, bv. je browsergeschiedenis, de instellingen van Teams of opgeslagen spellen.\n\nVerborgen: Windows verbergt de map, zodat gebruikers ze niet per ongeluk aanpassen. Zichtbaar maken in de Verkenner: View, Show, Hidden items.\n\n%APPDATA% is een systeemvariabele: een naam die Windows vervangt door een pad, bv. C:\\Users\\Jefke\\AppData\\Roaming. Typ ze in de navigatiebalk van de Verkenner en je komt meteen in die map, ook als hij verborgen is.\nTer info: %APPDATA% gaat naar de submap Roaming. %LOCALAPPDATA% gaat naar Local." },
  { v: "AppData: Local, LocalLow en Roaming", a: "3 subfolders, voor rechten en synchronisatie op het domein:\n• Local: enkel op deze pc, niet doorgegeven bij inloggen elders\n• LocalLow: minder rechten nodig om te schrijven (bv. protected mode van Internet Explorer)\n• Roaming: gesynchroniseerd via de Domain Controller, zodat je instellingen meegaan naar een andere pc in het domein", o: "User profiles", wit: true,
    uitleg: "AppData heeft 3 submappen. Programma's kiezen zelf in welke ze iets bewaren:\n\n• Local: gegevens die enkel op deze pc blijven, bv. grote tijdelijke bestanden of een cache. Log je in op een andere pc in het domein, dan gaan ze niet mee.\n• LocalLow: zoals Local, maar programma's met weinig rechten mogen hier schrijven. Bv. Internet Explorer in protected mode: een veiligere modus waarin de browser bijna nergens mag schrijven, zodat een kwaadaardige website weinig kan aanrichten.\n• Roaming: gegevens die meegaan. In een domein wordt deze map gesynchroniseerd via de server: log je in op een andere pc in het domein, dan krijg je daar dezelfde instellingen.\n\nRoaming = zwervend: de instellingen gaan mee met de gebruiker." },
  { v: "Wat krijgt elke gebruiker in Windows, en waar staan de profielfolders?", a: "Een Registry Hive en profielfolders, onder C:/Users.", o: "User profiles",
    uitleg: "Elke gebruiker krijgt twee dingen:\n• Een Registry Hive: zijn eigen deel van het register, met zijn persoonlijke instellingen (bv. achtergrond, instellingen van programma's). Het bestand heet NTUSER.DAT.\n• Profielfolders: zijn eigen mappen, zoals Documents, Downloads, Desktop en AppData.\n\nDe profielfolders staan in C:\\Users, met een map per gebruiker, bv. C:\\Users\\Jefke.\n\nZo heeft elke gebruiker zijn eigen bestanden en instellingen, en kan hij niet aan die van een ander." },
  { v: "Wat is AppData, en waarom zie je het niet?", a: "Een verborgen map waarin applicaties data en settings per gebruiker bewaren. Vink hidden items aan.", o: "User profiles",
    uitleg: "AppData = application data: de map waarin programma's hun gegevens en instellingen per gebruiker bewaren, bv. je browsergeschiedenis of de instellingen van Teams. Ze staat in je profielmap: C:\\Users\\<jouwnaam>\\AppData.\n\nJe ziet ze niet omdat ze verborgen is: Windows wil vermijden dat gebruikers per ongeluk instellingen van programma's wissen.\n\nZichtbaar maken in de Verkenner: View, Show, Hidden items aanvinken. Of typ %APPDATA% in de navigatiebalk." },
  { v: "Welke 3 subfolders heeft AppData, en waarom die opsplitsing?", a: "Local, LocalLow en Roaming: voor rechten en synchronisatie op het domein.", o: "User profiles",
    uitleg: "Local, LocalLow en Roaming.\n\nDe opsplitsing is er om twee redenen:\n• Rechten: in LocalLow mogen ook programma's met weinig rechten schrijven; in de andere mappen niet.\n• Synchronisatie op het domein: Roaming gaat mee naar een andere pc in het domein, Local en LocalLow blijven op deze pc.\n\nZo kan een programma kiezen: instellingen die overal moeten gelden, in Roaming; grote of tijdelijke bestanden in Local.\n\nZie de volgende kaart voor het verschil." },
  { v: "Wat is het verschil tussen Local, LocalLow en Roaming?", a: "Local: enkel op deze pc, niet doorgegeven.\nLocalLow: minder rechten nodig om te schrijven.\nRoaming: gesynchroniseerd via de Domain Controller, gaat mee naar een andere pc in het domein.", o: "User profiles",
    uitleg: "• Local: blijft op deze pc. Log je in op een andere pc in het domein, dan gaat het niet mee. Gebruikt voor grote of tijdelijke bestanden, bv. een cache.\n• LocalLow: zoals Local, maar met lagere beveiliging: ook programma's met weinig rechten mogen hier schrijven. Bv. Internet Explorer in protected mode (een veiligere modus waarin de browser bijna nergens mag schrijven).\n• Roaming: wordt gesynchroniseerd via de server van het domein. Log je in op een andere pc in het domein, dan krijg je daar dezelfde instellingen.\n\nRoaming = zwervend: de instellingen gaan mee met de gebruiker." },
  { v: "Ga snel naar de AppData-map van je profiel in de Verkenner.", a: "Typ %APPDATA% in de navigatiebalk", o: "User profiles", oefening: true,
    uitleg: "%APPDATA% = een systeemvariabele: Windows vervangt ze door het pad naar de AppData-map van je profiel." },
  // ===== Het register =====
  { v: "Het register: wat is het?", a: "Een centrale, hiërarchische database om het systeem te configureren voor gebruikers, toepassingen en apparaten.\n• Bevat o.a. profielen per gebruiker, geïnstalleerde toepassingen en welke documenten ze maken, instellingen van vensters en pictogrammen, de hardware en de poorten in gebruik.\n• Vervangt de tekst-configuratiebestanden van MS-DOS en Windows 3.x (Autoexec.bat, Config.sys).", o: "Het register", wit: true,
    uitleg: "Het register (registry) is één grote database waarin Windows bijna al zijn instellingen bewaart.\n\nCentraal = alle instellingen op één plaats, voor Windows, alle programma's en alle hardware.\nHiërarchisch = opgebouwd als een boom, net zoals mappen en submappen in de Verkenner:\n• bovenaan staan 5 hoofdsleutels, bv. HKEY_LOCAL_MACHINE (instellingen voor de hele pc) en HKEY_CURRENT_USER (instellingen van de gebruiker die nu ingelogd is);\n• daaronder sleutels en subsleutels (zoals mappen);\n• in een sleutel staan waarden (zoals bestanden), elk met een naam, een datatype en een inhoud.\n\nVroeger, in MS-DOS en Windows 3.x, stonden de instellingen in losse tekstbestanden, zoals Autoexec.bat en Config.sys. Het register vervangt die." },
  { v: "Registeronderdeel (hive)", a: "Een groep sleutels, subsleutels en waarden, met ondersteuningsbestanden (back-ups).\nDe bestanden (behalve HKEY_CURRENT_USER) staan in c:/Windows/System32/config, of %SystemRoot%\\System32\\Config.", o: "Het register", wit: true,
    uitleg: "Een registeronderdeel (hive) is een groot hoofddeel van het register met zijn eigen bestand op de schijf.\n\nSleutel = zoals een map in het register. Subsleutel = een sleutel in een sleutel. Waarde = een instelling in een sleutel, met een naam en een inhoud.\n\nOndersteuningsbestanden = extra bestanden bij elke hive, o.a. back-ups en logbestanden, zodat het register hersteld kan worden als er iets misloopt.\n\nWaar staan de bestanden: in C:\\Windows\\System32\\config. %SystemRoot% is een systeemvariabele die naar de map Windows wijst (meestal C:\\Windows).\nUitzondering: HKEY_CURRENT_USER, de instellingen van de ingelogde gebruiker. Dat bestand (NTUSER.DAT) staat in de profielmap van de gebruiker, bv. C:\\Users\\Jefke." },
  { v: "regedit", a: "Met regedit bekijk en wijzig je het register. Waarden hebben een datatype, bv. DWORD (Double-Word).", o: "Het register", wit: true,
    uitleg: "regedit = de Registry Editor: het programma waarmee je het register bekijkt en wijzigt. Openen: Windows + R, regedit typen, Enter.\n\nLinks zie je de boom met sleutels (zoals mappen), rechts de waarden in de gekozen sleutel.\n\nElke waarde heeft een datatype: wat voor soort gegevens erin staat. Bv.:\n• DWORD (Double-Word): een getal van 32 bits. Een word is 16 bits, double = dubbel. Vaak gebruikt als aan/uit-schakelaar: 0 = uit, 1 = aan.\n• String (REG_SZ): tekst." },
  { v: "Het register aanpassen: waarom, en eerst een back-up", a: "• Gebruikt om virussen volledig te verwijderen, of bij hardwareproblemen (bv. een cd-rom die niet herkend wordt).\n• Opgelet: een verkeerde waarde kan het systeem serieus in de war sturen!\n• Maak eerst een back-up: kopieer de registerbestanden, of exporteer het register (of een deel) en importeer het later.", o: "Het register", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_regedit_export.jpg",
    uitleg: "Waarom het register aanpassen:\n• Een virus verwijderen: veel virussen zetten zichzelf in het register, zodat ze bij elke opstart meestarten. Om het virus volledig te verwijderen, moet je die waarden ook wissen.\n• Hardwareproblemen: soms staat een foute instelling voor een apparaat in het register, bv. waardoor een cd-rom-station niet herkend wordt.\n\nOpgelet: Windows leest het register voortdurend. Een verkeerde waarde kan ervoor zorgen dat programma's of zelfs Windows niet meer werken. Er is geen knop Ongedaan maken.\n\nDaarom maak je eerst een back-up:\n• Exporteren: in regedit, File, Export. Je kiest het hele register (All) of één sleutel, en Windows schrijft het naar een .reg-bestand.\n• Importeren: File, Import, en kies dat .reg-bestand. De waarden uit de back-up worden teruggezet." },
  { v: "Register-tweak: laatst ingelogde gebruiker verbergen", a: "Op eigen risico: de laatst ingelogde gebruiker niet tonen op het loginscherm.\n• Key: HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\n• Value: dontdisplaylastusername, type DWORD, data 0 = no effect, 1 = niet tonen", o: "Het register", wit: true,
    uitleg: "In een kantooromgeving is het een nadeel dat alle inlognamen zichtbaar zijn voor een inbreker. Kan ook via group policies." },
  { v: "Wat is het register?", a: "Een centrale, hiërarchische database om het systeem te configureren voor één of meer gebruikers, toepassingen en apparaten.", o: "Het register",
    uitleg: "Het register is één grote database waarin Windows bijna al zijn instellingen bewaart.\n\nCentraal = alle instellingen op één plaats.\nHiërarchisch = opgebouwd als een boom: sleutels met subsleutels (zoals mappen), en daarin waarden (de instellingen).\n\nConfigureren voor:\n• gebruikers: de persoonlijke instellingen van elke gebruiker;\n• toepassingen: de instellingen van elk geïnstalleerd programma;\n• apparaten: welke hardware er is en welke driver erbij hoort." },
  { v: "Geef voorbeelden van wat het register bevat.", a: "Profielen per gebruiker, geïnstalleerde toepassingen en welke documenten ze maken, instellingen van eigenschappenvensters en pictogrammen, de hardware en de poorten in gebruik.", o: "Het register",
    uitleg: "Voorbeelden uit de cursus, met wat ze betekenen:\n• Profielen per gebruiker: de persoonlijke instellingen van elke gebruiker, bv. zijn achtergrond.\n• Geïnstalleerde toepassingen en welke documenten ze maken: bv. dat een .docx-bestand met Word opent.\n• Instellingen van eigenschappenvensters en pictogrammen: hoe vensters en pictogrammen eruitzien.\n• De hardware: welke apparaten er in de pc zitten en welke driver erbij hoort.\n• De poorten in gebruik: welke aansluitingen (bv. USB) gebruikt worden." },
  { v: "Welke bestanden vervangt het register?", a: "De tekst-configuratiebestanden van MS-DOS en Windows 3.x, zoals Autoexec.bat en Config.sys.", o: "Het register",
    uitleg: "MS-DOS en Windows 3.x zijn de voorgangers van het huidige Windows (jaren 1980 en begin 1990).\n\nToen stonden de instellingen in losse tekstbestanden, zoals:\n• Autoexec.bat: commando's die bij het opstarten automatisch uitgevoerd werden;\n• Config.sys: de instellingen voor het geheugen en de drivers.\n\nElk programma kon ook zijn eigen tekstbestand hebben. Dat werd onoverzichtelijk. Het register zet al die instellingen in één centrale database." },
  { v: "Wat is een registeronderdeel, en waar staan de bestanden?", a: "Een groep sleutels, subsleutels en waarden met ondersteuningsbestanden (back-ups). Behalve HKEY_CURRENT_USER in c:/Windows/System32/config (%SystemRoot%\\System32\\Config).", o: "Het register",
    uitleg: "Een registeronderdeel (hive) is een groot hoofddeel van het register, met zijn eigen bestand op de schijf.\n\nSleutel = zoals een map in het register. Subsleutel = een sleutel in een sleutel. Waarde = een instelling, met een naam en een inhoud.\n\nOndersteuningsbestanden = extra bestanden bij elke hive (back-ups en logbestanden), zodat het register hersteld kan worden als er iets misloopt.\n\nDe bestanden staan in C:\\Windows\\System32\\config. %SystemRoot% is een systeemvariabele die naar de Windows-map wijst, meestal C:\\Windows.\n\nUitzondering: HKEY_CURRENT_USER (de instellingen van de ingelogde gebruiker). Dat bestand, NTUSER.DAT, staat in de profielmap van de gebruiker, bv. C:\\Users\\Jefke." },
  { v: "Geef een datatype uit het register.", a: "DWORD (Double-Word).", o: "Het register",
    uitleg: "Elke waarde in het register heeft een datatype: wat voor soort gegevens erin staat.\n\nDWORD = Double-Word: een getal van 32 bits. Een word is 16 bits; double = dubbel, dus 32 bits.\n\nDWORD-waarden worden vaak gebruikt als aan/uit-schakelaar: 0 = uit, 1 = aan. Bv. dontdisplaylastusername = 1.\n\nEen ander datatype is String (REG_SZ): tekst." },
  { v: "Wanneer gebruik je het register, en waarop let je?", a: "Om virussen volledig te verwijderen of bij hardwareproblemen (bv. een cd-rom die niet herkend wordt). Een verkeerde waarde kan het systeem serieus in de war sturen: maak eerst een back-up.", o: "Het register",
    uitleg: "Wanneer:\n• Een virus volledig verwijderen: veel virussen zetten zichzelf in het register, zodat ze bij elke opstart meestarten. Die waarden moet je ook wissen.\n• Hardwareproblemen: soms staat er een foute instelling voor een apparaat in het register, bv. waardoor een cd-rom-station niet herkend wordt.\n\nWaarop let je: Windows leest het register voortdurend. Een verkeerde waarde kan programma's of zelfs Windows laten vastlopen, en er is geen knop Ongedaan maken. Daarom maak je eerst een back-up, zodat je de oude toestand kan terugzetten." },
  { v: "Hoe maak je een back-up van het register?", a: "De registerbestanden kopiëren, of een export maken van het hele register (of een deel) en die later importeren.", o: "Het register",
    uitleg: "Twee manieren:\n• De registerbestanden zelf kopiëren (uit C:\\Windows\\System32\\config).\n• Exporteren met regedit: File, Export. Kies All (het hele register) of Selected branch (enkel de sleutel die je aanpast). Windows schrijft alles naar een .reg-bestand.\n\nTerugzetten: in regedit, File, Import, en kies het .reg-bestand. Windows zet de waarden uit de back-up terug.\n\nLet op: importeren zet de waarden uit de back-up terug, maar wist geen waarden die je na de back-up nieuw hebt toegevoegd." },
  { v: "Open het register.", a: "  Win+R\n  regedit", o: "Het register", oefening: true,
    uitleg: "Stap voor stap:\n1. Druk Windows + R: het venster Run (Uitvoeren) opent. Daarin typ je de naam van een programma.\n2. Typ regedit en druk Enter.\n3. UAC vraagt toestemming: regedit heeft adminrechten nodig.\n\nregedit = de Registry Editor: het programma om het register te bekijken en te wijzigen." },
  { v: "Ga in het register naar de locaties van de hives.", a: "regedit → HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\hivelist", o: "Het register", oefening: true,
    uitleg: "hivelist is een sleutel in het register die toont waar elk registeronderdeel (hive) als bestand op de schijf staat.\n\nStap voor stap:\n1. Open regedit.\n2. Klap links HKEY_LOCAL_MACHINE open (de instellingen van de hele pc).\n3. Ga naar SYSTEM, dan CurrentControlSet, dan Control, dan hivelist.\n\nRechts zie je per hive het pad naar het bestand, bv. \\REGISTRY\\MACHINE\\SYSTEM in C:\\Windows\\System32\\config\\SYSTEM.\n\nSnel: je kan het pad ook plakken in de adresbalk bovenaan regedit." },
  { v: "Maak een back-up van je register, pas de tweak aan en zet de back-up terug.", a: "regedit → File → Export (All)\nHKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System → dontdisplaylastusername (DWORD) = 1\nFile → Import → je back-up", o: "Het register", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_regedit_export.jpg",
    uitleg: "Stap voor stap:\n1. Open regedit.\n2. Back-up: File, Export. Kies onderaan All (het hele register), geef een naam en klik op Save.\n3. Ga naar HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System.\n4. Dubbelklik rechts op dontdisplaylastusername (DWORD) en zet de waarde op 1.\n5. Meld af: op het inlogscherm staat de naam van de laatste gebruiker niet meer.\n6. Terugzetten: File, Import, en kies je back-up.\n7. Controleer dat de waarde terug op 0 staat.\n\nTweak = een kleine aanpassing van een instelling. Een back-up van het hele register is groot en het exporteren duurt even.\n\nLet op: importeren zet de waarden uit de back-up terug, maar wist geen waarden die je nieuw hebt toegevoegd. dontdisplaylastusername bestaat al (op 0), daarom staat ze na het importeren weer op 0." },
  { v: "Welke waarde zorgt dat de laatst ingelogde gebruiker niet getoond wordt, en waarom wil je dat?", a: "dontdisplaylastusername (DWORD) op 1. In een kantoor zijn de inlognamen anders bekend bij iemand die wil inbreken.", o: "Het register",
    uitleg: "dontdisplaylastusername = don't display last user name: toon de naam van de laatste gebruiker niet. Het is een DWORD (een getal): 1 = aan, 0 = uit.\n\nNormaal toont het inlogscherm van Windows de naam van de gebruiker die het laatst ingelogd was. Je hoeft dan enkel het wachtwoord in te vullen.\n\nWie wil inbreken, moet een gebruikersnaam en een wachtwoord raden. Toont het scherm de naam al, dan is de helft gekend. Met deze instelling moet hij ook de naam raden. In een kantoor met veel gebruikers is dat een extra beveiliging." },
  { v: "Registry hives", a: "Een hive is een groot hoofddeel van het register, met zijn eigen bestand op de schijf, bv. SYSTEM, SOFTWARE, SAM, SECURITY en per gebruiker NTUSER.DAT. Windows laadt ze bij het opstarten of aanmelden.", o: "Het register", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus.\n\nHet register is in grote hoofddelen verdeeld: de hives. Elke hive staat als apart bestand op de schijf:\n• SYSTEM: de instellingen voor het opstarten en de hardware;\n• SOFTWARE: de instellingen van Windows en de geïnstalleerde programma's;\n• SAM (Security Account Manager): de lokale gebruikers en hun wachtwoorden (versleuteld);\n• SECURITY: beveiligingsinstellingen;\n• NTUSER.DAT: per gebruiker, zijn persoonlijke instellingen (in zijn profielmap).\n\nWindows laadt de hives van de pc bij het opstarten, en de hive van een gebruiker als hij aanmeldt." },
  // ===== Systeemvariabelen =====
  { v: "Systeemvariabelen", a: "• Paden en gegevens worden in variabelen bijgehouden; alle programma's kunnen ze gebruiken.\n• Visueel: Verkenner → rechtsklik This PC → Properties → Advanced system settings → Environment Variables.\n• Voor een gebruiker (User variables) of voor het hele systeem (System variables).\n• path: bij het starten van een programma vanuit de prompt (bv. notepad) zoekt CMD de .exe in de mappen van path. Toon de waarde met het commando path.", o: "Systeemvariabelen", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_omgevingsvariabelen.jpg",
    uitleg: "Een variabele is een naam met een waarde, bv. USERNAME = Jefke. Windows bewaart zo paden en gegevens die alle programma's nodig hebben. Een programma vraagt dan gewoon de waarde van USERNAME, in plaats van zelf te zoeken wie ingelogd is.\n\nIn CMD gebruik je een variabele met procenttekens: echo %USERNAME% toont Jefke. Windows vervangt %USERNAME% door de waarde.\n\nVisueel openen, stap voor stap:\n1. Open de Verkenner.\n2. Rechtsklik op This PC en kies Properties.\n3. Klik op Advanced system settings.\n4. Klik op Environment Variables.\n\nJe ziet twee lijsten:\n• User variables: gelden enkel voor de gebruiker die nu ingelogd is.\n• System variables: gelden voor alle gebruikers van de pc.\n\npath = een lijst van mappen, gescheiden door puntkomma's. Typ je in CMD notepad, dan zoekt CMD eerst in de huidige map en daarna in elke map van path naar notepad.exe. Staat de map van een programma niet in path, dan moet je het volledige pad typen." },
  { v: "path aanpassen en variabelen tonen", a: "• Voorbeeld: PATH=C:\\Windows\\system32;C:\\Windows;C:\\Windows\\System32\\Wbem: Windows zoekt in die 3 mappen.\n• path=\"test\": overschrijft path; de oude waarde ben je kwijt (een nieuwe prompt herstelt ze). Blijvend wijzigen kan met setx (max. 1024 tekens).\n• Path = %path%;c:\\test: voegt c:\\test achteraan toe; ; scheidt de mappen.\n• Een variabele tonen: echo + de naam tussen %, bv. echo %computername%.\n\nOpdracht: zoek met echo de waarde en de uitleg van Appdata, Computername, Localappdata, Path, Pathext, Programfiles en Username.", o: "Systeemvariabelen", wit: true,
    uitleg: "Good to know: ook Errorlevel, Homedrive, Homepath, Os, Processor_architecture, Processor_identifier en Temp." },
  { v: "Good to know: GodMode (niet te kennen)", a: "• GodMode bestaat sinds Windows 7: een snelkoppeling naar een overzicht van alle handige tools om je systeem te beheren.\n• Maak een map (bv. op je bureaublad) met de naam:\nGodMode.{ED7BA470-8E54-465E-825C-99712043E01C}", o: "Systeemvariabelen", extra: true, nietTeKennen: true,
    uitleg: "Good to know: niet te kennen leerstof.\n\nGodMode is geen apart programma, maar een map met een speciale naam. De lange code tussen de accolades is een vaste code (een GUID) die Windows herkent. Geef je een map die naam, dan toont Windows er geen bestanden in, maar een lijst van alle instellingen van het Configuratiescherm (Control Panel) op één plaats.\n\nHandig om snel een instelling te vinden zonder door menu's te moeten zoeken." },
  { v: "Open de systeemvariabelen visueel.", a: "Verkenner → rechtsklik This PC → Properties → Advanced system settings → Environment Variables", o: "Systeemvariabelen", oefening: true,
    uitleg: "Stap voor stap:\n1. Open de Verkenner (Windows + E).\n2. Rechtsklik links op This PC en kies Properties.\n3. Klik op Advanced system settings: het venster System Properties opent.\n4. Klik onderaan op Environment Variables.\n\nBovenaan staan de User variables (enkel voor jou), onderaan de System variables (voor alle gebruikers). Je kan er variabelen bekijken, toevoegen, wijzigen en verwijderen." },
  { v: "Voor wie kan je systeemvariabelen aanmaken?", a: "Voor een gebruiker (User variables) of voor het hele systeem (System variables).", o: "Systeemvariabelen",
    uitleg: "• User variables: gelden enkel voor de gebruiker die ingelogd is. Bv. TEMP wijst naar een map in jouw profiel. Een andere gebruiker heeft zijn eigen waarde.\n• System variables: gelden voor alle gebruikers van de pc. Bv. windir = C:\\Windows. Om ze te wijzigen heb je adminrechten nodig.\n\nBestaat een variabele in beide lijsten (zoals path), dan gebruikt Windows ze samen: eerst de mappen van het systeem, dan die van de gebruiker." },
  { v: "Waarvoor dient de variabele path?", a: "CMD zoekt een programma dat je start (bv. notepad.exe) in de mappen van path.", o: "Systeemvariabelen",
    uitleg: "path is een systeemvariabele met een lijst van mappen, gescheiden door puntkomma's, bv. C:\\Windows\\system32;C:\\Windows;...\n\nTyp je in CMD de naam van een programma, bv. notepad, dan zoekt CMD:\n1. eerst in de map waar je nu staat;\n2. daarna, één voor één, in elke map van path, naar notepad.exe.\n\nVindt CMD het niet, dan krijg je de fout: 'notepad' is not recognized as an internal or external command.\n\nZo kan je programma's starten door enkel hun naam te typen, zonder het volledige pad." },
  { v: "Toon de huidige waarde van path.", a: "C:\\> path", o: "Systeemvariabelen", oefening: true,
    uitleg: "Typ path en druk Enter. CMD toont de waarde van de variabele path: een lange lijst van mappen, gescheiden door puntkomma's.\n\nIn die mappen zoekt CMD naar een programma als je enkel de naam typt.\n\nHetzelfde resultaat met: echo %path%" },
  { v: "Voeg c:\\test achteraan toe aan path, zonder de oude waarde te verliezen.", a: "C:\\> path=%path%;c:\\test", o: "Systeemvariabelen", oefening: true,
    uitleg: "path= = geef path een nieuwe waarde.\n%path% = de huidige waarde (zo verlies je die niet).\n;c:\\test = ; scheidt de mappen, c:\\test komt erachter." },
  { v: "Wat is het nadeel van path=\"test\", en hoe wijzig je path blijvend?", a: "De vorige waarde ben je kwijt (een nieuwe prompt herstelt ze). Blijvend met setx, maar dat werkt maar met 1024 tekens.", o: "Systeemvariabelen",
    uitleg: "path=\"test\" (of set path=test) geeft path een nieuwe waarde: enkel de map test. De vorige lijst met mappen is weg. Daarna vindt CMD bv. notepad niet meer, omdat C:\\Windows niet meer in path staat.\n\nDie wijziging geldt enkel in dit ene CMD-venster. Open je een nieuwe prompt, dan krijg je de oude waarde terug.\n\nBlijvend wijzigen doe je met setx: het bewaart de nieuwe waarde in het register, zodat elke nieuwe prompt ze gebruikt. Nadeel: setx kapt de waarde af na 1024 tekens. path is vaak langer, dus je kan zo een deel van path kwijtraken. Veiliger: via Environment Variables in het venster." },
  { v: "Toon de naam van je computer met een variabele.", a: "C:\\> echo %computername%", o: "Systeemvariabelen", oefening: true,
    uitleg: "echo = geef tekst.\n%computername% = de variabele met de naam van je computer. Een variabele tonen: echo + de naam tussen %." },
  { v: "Toon de waarden van Appdata, Localappdata, Path, Pathext, Programfiles en Username.", a: "C:\\> echo %appdata%\nC:\\> echo %localappdata%\nC:\\> echo %path%\nC:\\> echo %pathext%\nC:\\> echo %programfiles%\nC:\\> echo %username%", o: "Systeemvariabelen", oefening: true,
    uitleg: "echo %naam% = toon de waarde van een systeemvariabele: Windows vervangt %naam% door die waarde.\nDe uitleg per variabele staat op de extra kaart 'Uitleg bij de systeemvariabelen'." },
  { v: "Uitleg bij de systeemvariabelen", a: "De cursus vraagt de uitleg zelf op te zoeken:", o: "Systeemvariabelen", extra: true,
    tabel: [
      ["Variabele", "Uitleg"],
      ["Appdata", "de map Roaming van je profiel (AppData\\Roaming)"],
      ["Computername", "de naam van de pc"],
      ["Localappdata", "de map Local van je profiel (AppData\\Local)"],
      ["Path", "de mappen waarin CMD programma's zoekt"],
      ["Pathext", "de extensies die als programma gelden (.COM;.EXE;.BAT;.CMD;...)"],
      ["Programfiles", "de map met geïnstalleerde programma's (C:\\Program Files)"],
      ["Username", "de naam van de ingelogde gebruiker"]
    ],
    uitleg: "Elk van deze variabelen gebruik je in CMD met procenttekens, bv. echo %USERNAME%. Windows vervangt dan de naam door de waarde.\n\nZo kan een programma of script werken op elke pc, voor elke gebruiker: in plaats van C:\\Users\\Jefke\\AppData\\Roaming te schrijven, schrijft het %APPDATA%, en Windows vult de juiste map in.\n\nPathext: typ je notepad zonder extensie, dan probeert CMD de extensies uit deze lijst (.COM, .EXE, .BAT, ...) tot het een bestand vindt." },
  // ===== Taken automatiseren =====
  { v: "Task Scheduler: het venster", a: "• 3 panelen: links de bibliotheek, in het midden de taken, rechts het actievenster.\n• Er staan al taken gepland, bv. MicrosoftEdgeUpdateTaskMachineUA (elke dag).", o: "Taken automatiseren", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_taakplanner.jpg",
    uitleg: "De Task Scheduler (Taakplanner) laat Windows automatisch een programma starten op een bepaald moment of bij een bepaalde gebeurtenis, bv. elke dag om 16u45 of bij het opstarten.\n\nOpenen: typ Task Scheduler in het zoekveld van Start.\n\nDe 3 panelen:\n• Links: de bibliotheek (Task Scheduler Library), met alle taken in mappen.\n• Midden: de taken in de gekozen map, met hun trigger (wanneer ze starten) en wanneer ze het laatst liepen.\n• Rechts: het actievenster: knoppen om taken te maken, te starten, uit te schakelen of te verwijderen.\n\nWindows en programma's plannen zelf ook taken, bv. MicrosoftEdgeUpdateTaskMachineUA: zoekt elke dag naar updates voor de browser Edge." },
  { v: "Task Scheduler: een Basic Task maken", a: "Voorbeeld: de pc uitschakelen om 16u45.\nCreate Basic Task → naam en beschrijving → dagelijks → programma starten: Shutdown.exe (in c:\\Windows\\System32) met parameter -S (-H sluimerstand, -R herstart, -L afmelden) → voltooien.\nProbeer ook -S -T 60 -C \"...\": met een boodschap, na 60 seconden.", o: "Taken automatiseren", wit: true,
    uitleg: "Extra uit de cursus: maak een taak die de downloadfolder van alle gebruikers elke dag leegmaakt, met een zelfgeschreven .bat-bestand." },
  { v: "Task Scheduler: ook als iemand anders ingelogd is", a: "Een Basic Task draait niet als iemand anders ingelogd is.\nOplossing: Eigenschappen → Algemeen → uitvoeren ongeacht of de gebruiker is aangemeld.", o: "Taken automatiseren", wit: true,
    uitleg: "Een Basic Task maak je met de eenvoudige wizard (Create Basic Task). Standaard staat ze op Run only when user is logged on: ze loopt enkel als jij (de gebruiker die de taak maakte) ingelogd bent.\n\nIs er iemand anders ingelogd, of niemand, dan loopt de taak dus niet.\n\nOplossing, stap voor stap:\n1. Dubbelklik op de taak (Properties).\n2. Tabblad General.\n3. Kies Run whether user is logged on or not (uitvoeren ongeacht of de gebruiker is aangemeld).\n4. Klik op OK en vul je wachtwoord in: Windows heeft het nodig om de taak met jouw rechten te starten als je niet ingelogd bent." },
  { v: "Task Scheduler: geschiedenis", a: "Geschiedenis inschakelen in het rechterpaneel. Daarna: dubbelklik op een taak → tabblad Geschiedenis.", o: "Taken automatiseren", wit: true,
    uitleg: "Standaard houdt de Task Scheduler niet bij wanneer een taak liep en of dat lukte.\n\nStap voor stap:\n1. Klik rechts in het actievenster op Enable All Tasks History.\n2. Wacht tot een taak gelopen heeft.\n3. Dubbelklik op de taak en kies het tabblad History.\n\nJe ziet elke keer dat de taak startte en stopte, en of er een fout was. Handig als een taak niet doet wat je verwacht." },
  { v: "Uit welke 3 panelen bestaat de Task Scheduler?", a: "Links de bibliotheek met alle taken, in het midden de taken zelf, rechts het actievenster om ze te beheren.", o: "Taken automatiseren",
    uitleg: "• Links: de bibliotheek (Task Scheduler Library): alle taken, geordend in mappen, zoals in de Verkenner.\n• Midden: de taken in de map die je links kiest, met hun naam, status, trigger (wanneer ze starten) en wanneer ze het laatst en het volgend liepen. Klik je op een taak, dan zie je eronder de details.\n• Rechts: het actievenster: knoppen om taken te maken (Create Basic Task, Create Task), te starten (Run), uit te schakelen (Disable) of te verwijderen (Delete)." },
  { v: "Laat de taak MicrosoftEdgeUpdateTaskMachineUA enkel lopen als de pc 10 minuten idle is.", a: "Task Scheduler → de taak → Properties → Conditions → Start the task only if the computer is idle for: 10 minutes", o: "Taken automatiseren", oefening: true,
    uitleg: "Idle = de pc doet niets: niemand gebruikt muis of toetsenbord, en de processor is weinig bezig.\n\nZo stoort de update je niet terwijl je werkt: ze start enkel als je pc al 10 minuten niets doet.\n\nStap voor stap:\n1. Open de Task Scheduler en klik links op Task Scheduler Library.\n2. Dubbelklik in het midden op MicrosoftEdgeUpdateTaskMachineUA (Properties).\n3. Tabblad Conditions.\n4. Vink Start the task only if the computer is idle for aan, en kies 10 minutes.\n5. Klik op OK." },
  { v: "Maak een taak die je pc elke dag om 16u45 uitschakelt.", a: "Create Basic Task → naam en beschrijving → Daily, 16:45 → Start a program\nProgramma: c:\\Windows\\System32\\shutdown.exe, parameter -S → Finish", o: "Taken automatiseren", oefening: true,
    uitleg: "Stap voor stap:\n1. Open de Task Scheduler.\n2. Klik rechts op Create Basic Task.\n3. Geef een naam (bv. Pc uit) en een beschrijving. Next.\n4. Trigger: kies Daily (elke dag). Next.\n5. Kies het startuur 16:45:00. Next.\n6. Action: kies Start a program. Next.\n7. Program/script: c:\\Windows\\System32\\shutdown.exe\n8. Add arguments: -S\n9. Klik op Finish.\n\nshutdown.exe = het programma van Windows dat de pc uitschakelt, herstart of afmeldt. Het argument -S betekent: uitschakelen (shut down).\n\nTer info: je kan het ook eerst testen in CMD met shutdown -s; met shutdown -a breek je het af." },
  { v: "Wat doen de parameters -S, -H, -R en -L van shutdown?", a: "-S = uitschakelen, -H = sluimerstand, -R = herstarten, -L = afmelden.", o: "Taken automatiseren",
    uitleg: "shutdown.exe is het programma van Windows om de pc uit te schakelen, te herstarten of af te melden. Met een parameter (argument) kies je wat het doet:\n• -S = shut down: de pc uitschakelen.\n• -H = hibernate: sluimerstand. Het werkgeheugen wordt naar de schijf geschreven en de pc gaat uit; bij het opstarten gaat je werk verder waar je was.\n• -R = restart: herstarten.\n• -L = log off: de gebruiker afmelden; de pc blijft aan.\n\nIn CMD: shutdown -r herstart de pc. Hoofd- of kleine letters maken niet uit." },
  { v: "Sluit de pc af binnen 60 seconden, met een waarschuwing.", a: "C:\\> shutdown -S -T 60 -C \"OVER PRECIES ÉÉN MINUUT SLUIT DE PC AF. SLA NU AL JE GEGEVENS OP!\"", o: "Taken automatiseren", oefening: true,
    uitleg: "shutdown = de pc afsluiten.\n-S = shut down (afsluiten).\n-T 60 = na 60 seconden.\n-C \"…\" = de waarschuwing die de gebruiker ziet.\nIn de cursus zijn dit de parameters van de taak. Annuleren: shutdown -A." },
  { v: "Waarom loopt een Basic Task soms niet, en hoe los je dat op?", a: "Niet als iemand anders ingelogd is. Eigenschappen → Algemeen → uitvoeren ongeacht of de gebruiker wel of niet is aangemeld.", o: "Taken automatiseren",
    uitleg: "Een Basic Task staat standaard op Run only when user is logged on: ze loopt enkel als de gebruiker die de taak maakte, ingelogd is.\n\nIs er iemand anders ingelogd, of niemand, dan loopt de taak niet. Bv. je taak om 16u45 de pc uit te schakelen, gebeurt dan niet.\n\nOplossing:\n1. Dubbelklik op de taak (Properties).\n2. Tabblad General.\n3. Kies Run whether user is logged on or not.\n4. Vul je wachtwoord in: Windows heeft het nodig om de taak met jouw rechten te starten als je niet ingelogd bent." },
  { v: "Hoe zie je een gedetailleerde log van een taak?", a: "Rechts de geschiedenis van alle taken inschakelen; dubbelklik op een taak → tabblad Geschiedenis.", o: "Taken automatiseren",
    uitleg: "Standaard bewaart de Task Scheduler geen geschiedenis van de taken.\n\nStap voor stap:\n1. Klik rechts in het actievenster op Enable All Tasks History.\n2. Dubbelklik op een taak.\n3. Tabblad History.\n\nJe ziet elke keer dat de taak startte en stopte, en of er een fout was. Zo zoek je uit waarom een taak niet deed wat je verwachtte." },
  // ===== Power Options =====
  { v: "Power Options", a: "• Rechtsklik op de startknop → Power options: wanneer scherm en pc in slaapstand gaan.\n• Handiger: Additional power settings, bv. Hibernate (de)activeren. Hibernate is niet beschikbaar op de VM's, wel op je laptop.\n\nOpdracht: zorg dat de harde schijf nooit deactiveert.", o: "Power Options", wit: true,
    uitleg: "Power Options (Energiebeheer) bepaalt hoe je pc met stroom omgaat: wanneer het scherm uitgaat en wanneer de pc in slaapstand gaat als je hem niet gebruikt.\n\nSlaapstand (sleep): de pc gaat in een zuinige stand, maar het werkgeheugen blijft onder stroom. Je werk staat er meteen terug.\nHibernate (sluimerstand): het werkgeheugen wordt naar de schijf geschreven en de pc gaat helemaal uit. Zie de groene kaart.\n\nAdditional power settings opent het oudere venster met meer instellingen, bv. Hibernate aan- of uitzetten, en de geavanceerde instellingen (zoals wanneer de harde schijf uitgaat).\n\nOp de VM's van school kan Hibernate niet; op je laptop wel." },
  { v: "Wat stel je in bij Power Options, en waar zitten de handigste zaken?", a: "Wanneer het scherm en de pc in slaapstand gaan. Het handigste zit onder Additional power settings, bv. Hibernate (de)activeren.", o: "Power Options",
    uitleg: "Je stelt in wanneer het scherm uitgaat en wanneer de pc in slaapstand gaat, als je hem een tijd niet gebruikt. Zo bespaar je stroom (en batterij op een laptop).\n\nOpenen: rechtsklik op de startknop en kies Power Options.\n\nDe handigste instellingen zitten onder Additional power settings (het oudere venster), bv.:\n• Hibernate (sluimerstand) aan- of uitzetten;\n• wat de aan/uit-knop doet;\n• de geavanceerde instellingen, zoals wanneer de harde schijf uitgaat." },
  { v: "Zorg dat de harde schijf nooit deactiveert.", a: "Rechtsklik startknop → Power Options → Additional power settings → Change plan settings → Change advanced power settings → Hard disk → Turn off hard disk after: Never", o: "Power Options", oefening: true,
    uitleg: "Om stroom te besparen, zet Windows de harde schijf uit (de platters stoppen met draaien) als ze een tijd niet gebruikt wordt. Bij het volgende gebruik moet ze weer opstarten, en dat duurt enkele seconden.\n\nStap voor stap:\n1. Rechtsklik op de startknop en kies Power Options.\n2. Klik op Additional power settings.\n3. Klik bij je energiebeheerschema op Change plan settings.\n4. Klik op Change advanced power settings.\n5. Klap Hard disk open, dan Turn off hard disk after.\n6. Zet de waarde op 0 of kies Never.\n7. Klik op OK." },
  { v: "Hibernate", a: "Bij Hibernate (sluimerstand) schrijft Windows het hele werkgeheugen naar de schijf (hiberfil.sys) en schakelt de pc volledig uit. Voordeel: geen stroomverbruik, je werk blijft open. Nadeel: trager opstarten dan slaapstand, en het neemt schijfruimte in.", o: "Power Options", extra: true,
    uitleg: "De cursus vraagt dit op te zoeken; het antwoord staat niet in de cursus.\n\nHet werkgeheugen (RAM) verliest alles zodra er geen stroom meer is. Daarom:\n• Slaapstand (sleep): het RAM blijft onder stroom, de rest gaat in een zuinige stand. Snel terug, maar het verbruikt nog een beetje stroom. Valt de stroom of de batterij uit, dan ben je niet-opgeslagen werk kwijt.\n• Hibernate (sluimerstand): Windows schrijft alles uit het RAM naar het bestand hiberfil.sys op de schijf, en de pc gaat helemaal uit. Bij het opstarten leest Windows het terug: je programma's en documenten staan weer open.\n\nVoordeel: geen stroomverbruik, en je werk blijft bewaard.\nNadeel: opstarten duurt langer dan uit slaapstand, en hiberfil.sys neemt ongeveer evenveel schijfruimte in als een groot deel van je RAM." },
  // ===== Event Viewer =====
  { v: "Event Viewer: waarvoor?", a: "Events worden (zo goed als) altijd gelogd. De Event Viewer toont en filtert ze, om software- of hardwareproblemen te vinden.\nZoek je online, vermeld dan ook de source: elke applicatie kiest haar eigen Event ID's.", o: "Event Viewer", wit: true,
    uitleg: "Event = een gebeurtenis die Windows of een programma registreert, bv. de pc start op, een programma crasht, iemand logt in, een driver laadt niet.\n\nLoggen = Windows schrijft elk event met datum, uur en details in een logboek (log).\n\nDe Event Viewer (Logboeken) is het programma dat die logs toont. Je kan er filteren, bv. enkel de fouten van vandaag. Zo vind je de oorzaak van software- of hardwareproblemen.\n\nOpenen: rechtsklik op de startknop, Event Viewer.\n\nEvent ID = een nummer voor een soort event. Source = het programma of onderdeel dat het event maakte. Elke source kiest zelf zijn nummers: event 1000 van het ene programma betekent iets anders dan 1000 van een ander. Zoek je online, vermeld dan altijd de source en het Event ID samen." },
  { v: "Event Viewer: de 5 types", a: "• Application: geïnstalleerde software\n• Security: beveiliging\n• Setup: domain controller\n• System: Windows-systeemfiles\n• Forwarded Events: doorgestuurd door een andere computer", o: "Event Viewer", wit: true,
    uitleg: "Windows houdt verschillende logs bij, elk voor een soort events (onder Windows Logs):\n• Application: events van geïnstalleerde programma's, bv. een programma dat crasht.\n• Security: beveiliging, bv. wie inlogde, of een mislukte inlogpoging.\n• Setup: volgens de cursus de domain controller. Ter info: hier staan ook events over de installatie van updates en Windows-onderdelen.\n• System: events van Windows zelf, bv. drivers en services die starten of falen.\n• Forwarded Events: events die een andere computer naar deze pc doorstuurt. Zo kan een beheerder de events van veel pc's op één plaats bekijken." },
  { v: "Event Viewer: de levels", a: "• Information: iets veranderd, gestart of beëindigd\n• Warning: iets kan of begint mis te gaan\n• Error: iets misgegaan, niet te ernstig\n• Critical: iets grondig mis, waarschijnlijk gecrasht", o: "Event Viewer", wit: true,
    uitleg: "Elk event krijgt een level: hoe ernstig het is.\n\n• Information: gewone melding, er is niets mis. Iets veranderde, startte of stopte, bv. een service is gestart.\n• Warning: nog geen probleem, maar het kan er een worden, bv. de schijf raakt bijna vol.\n• Error: er ging iets mis, maar het systeem werkt verder, bv. een programma kon een bestand niet openen.\n• Critical: er ging iets grondig mis, bv. de pc crashte of werd onverwacht uitgeschakeld.\n\nBij een probleem filter je eerst op Error en Critical." },
  { v: "Event Viewer: properties, filters en taken", a: "• Event Properties: meer info per event.\n• Filters in het rechterpaneel.\n• Een taak aan een event koppelen: rechtsklik → Attach Task To This Event.", o: "Event Viewer", wit: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_attach_task.jpg",
    uitleg: "• Event Properties: dubbelklik op een event. Je ziet de details: de beschrijving, de source (welk programma), het Event ID, de datum, de gebruiker en de computer.\n• Filters: rechts in het actievenster, met Filter Current Log. Je toont enkel de events die je zoekt, bv. enkel Error van de laatste 24 uur, of één Event ID.\n• Een taak aan een event koppelen: rechtsklik op een event en Attach Task To This Event. Telkens dat event opnieuw gebeurt, start Windows automatisch een programma. Daarvoor maakt Windows een taak in de Task Scheduler." },
  { v: "Wat is de Event Viewer?", a: "Een tool om de logs van events in Windows ordelijk te bekijken en te filteren, om te zien of er software- of hardwareproblemen zijn.", o: "Event Viewer",
    uitleg: "Event = een gebeurtenis die Windows of een programma registreert, bv. de pc start op, iemand logt in, een programma crasht.\n\nLog = het logboek waarin Windows die events opschrijft, met datum, uur en details.\n\nDe Event Viewer toont die logs geordend en laat je filteren, bv. enkel de fouten van vandaag. Zo zie je wat er misliep en wanneer, en vind je de oorzaak van een software- of hardwareprobleem.\n\nOpenen: rechtsklik op de startknop, Event Viewer." },
  { v: "Geef de 5 types events.", a: "Application, Security, Setup, System en Forwarded Events.", o: "Event Viewer",
    uitleg: "Windows houdt een apart log bij per soort events. In de Event Viewer staan ze onder Windows Logs:\n• Application\n• Security\n• Setup\n• System\n• Forwarded Events\n\nZo zoek je gericht: een programma dat crasht vind je in Application, een mislukte inlogpoging in Security. Zie de volgende kaart voor wat elk type bevat." },
  { v: "Wat bevatten Application, Security, Setup, System en Forwarded Events?", a: "Application: geïnstalleerde software.\nSecurity: de beveiliging.\nSetup: de domain controller (enkel in een domein).\nSystem: de Windows-systeemfiles.\nForwarded Events: doorgestuurd door een andere computer.", o: "Event Viewer",
    uitleg: "• Application: events van geïnstalleerde programma's, bv. een programma dat crasht of een fout meldt.\n• Security: beveiliging, bv. wie inlogde en wanneer, en mislukte inlogpogingen.\n• Setup: volgens de cursus de domain controller (enkel in een domein). Ter info: hier staan ook events over de installatie van updates en Windows-onderdelen.\n• System: events van Windows zelf, bv. drivers en services die starten of falen, of de pc die opstart.\n• Forwarded Events: events die een andere computer naar deze pc doorstuurt. Zo kan een beheerder de events van veel pc's op één plaats bekijken." },
  { v: "Geef de 4 levels van een event, van minst tot meest ernstig.", a: "Information, Warning, Error en Critical.", o: "Event Viewer",
    uitleg: "Het level geeft aan hoe ernstig een event is, van minst naar meest ernstig:\n1. Information: gewone melding, niets mis.\n2. Warning: kan een probleem worden.\n3. Error: er ging iets mis.\n4. Critical: er ging iets grondig mis.\n\nBij een probleem filter je eerst op Error en Critical: dat zijn de events die iets met het probleem te maken kunnen hebben." },
  { v: "Wat betekent elk level?", a: "Information: iets veranderd, gestart of beëindigd.\nWarning: iets kan of begint mis te gaan.\nError: iets misgegaan, niet te ernstig.\nCritical: iets grondig mis, waarschijnlijk gecrasht.", o: "Event Viewer",
    uitleg: "• Information: niets mis. Er veranderde, startte of stopte iets, bv. een service is gestart of een update is geïnstalleerd.\n• Warning: nog geen probleem, maar het kan er een worden, bv. de schijf raakt bijna vol.\n• Error: er ging iets mis, maar het systeem werkt verder, bv. een programma kon niet starten of een bestand niet openen.\n• Critical: er ging iets grondig mis, bv. de pc crashte of werd onverwacht uitgeschakeld (bv. stroom weg)." },
  { v: "Waarom google je niet enkel op het Event ID?", a: "Elke applicatie bepaalt haar eigen Event ID's: vermeld ook de source (of de applicatienaam).", o: "Event Viewer",
    uitleg: "Event ID = een nummer voor een soort event. Source = het programma of onderdeel dat het event maakte (staat in de Event Viewer bij elk event).\n\nElke applicatie kiest zelf haar Event ID's. Hetzelfde nummer, bv. 1000, betekent bij het ene programma iets helemaal anders dan bij een ander.\n\nZoek je enkel op het nummer, dan vind je uitleg over de verkeerde events. Zoek daarom altijd op de source en het Event ID samen, bv. 'Application Error 1000'." },
  { v: "Zoek het event van een nieuwe RDP-connectie en maak er een custom filter voor.", a: "Event Viewer → rechterpaneel → Create Custom View → filter op het event\nSluit je RDP-connectie, verbind opnieuw en bekijk of het event erbij staat", o: "Event Viewer", oefening: true,
    uitleg: "RDP = Remote Desktop Protocol: de verbinding waarmee je op de VM werkt. Telkens je verbindt, logt Windows een event.\n\nCustom View = een eigen, bewaarde filter: je kiest welke events je wil zien, en Windows toont ze telkens in een eigen lijst links onder Custom Views.\n\nStap voor stap:\n1. Open de Event Viewer.\n2. Zoek het event van je RDP-verbinding (zie ter info).\n3. Klik rechts op Create Custom View.\n4. Kies het log en vul het Event ID in. Geef de view een naam.\n5. Sluit je RDP-verbinding, verbind opnieuw, en kijk of er een nieuw event in je view staat.\n\nHet event toont het IP-adres en de poort van de client: de pc van waaruit je verbindt.\n\nTer info: in het log Security is dat Event ID 4624 (succesvolle aanmelding) met Logon Type 10 (aanmelding via Remote Desktop)." },
  { v: "Koppel een taak aan een event.", a: "Event Viewer → rechtsklik op het event → Attach Task To This Event", o: "Event Viewer", oefening: true, img: "afbeeldingen/DesktopOS_windows_wc2/w2_attach_task.jpg",
    uitleg: "Een taak aan een event koppelen = telkens dat event opnieuw gebeurt, start Windows automatisch een programma of script. Bv. je krijgt een melding als een bepaalde fout opnieuw voorkomt.\n\nStap voor stap:\n1. Open de Event Viewer en zoek het event.\n2. Rechtsklik op het event en kies Attach Task To This Event.\n3. Er opent een wizard zoals bij Create Basic Task: geef een naam, kies Start a program en het programma.\n4. Klik op Finish.\n\nWindows maakt daarvoor een taak in de Task Scheduler, met het event als trigger." },
  // ===== schtasks, arp en netstat =====
  { v: "Extra oefeningen: schtasks, arp en netstat", a: "Niet te kennen, wel om commando's met argumenten en de help te trainen.\n• schtasks: taken uit de Task Scheduler aanmaken via het commando. Bekijk de help en maak een taak.\n• arp: een lijst van de fysieke adressen (MAC) op het netwerk. Bekijk de documentatie en toon de volledige ARP-tabel.\n• netstat: de status van je poorten. Laat ze elke 3 seconden vernieuwen, open een browser en kijk wat verandert; toon alle open poorten.", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true,
    uitleg: "Niet te kennen: extra oefeningen om commando's met argumenten en de help te trainen.\n\n• schtasks: hetzelfde als de Task Scheduler, maar via een commando. Bv. schtasks /create maakt een taak; schtasks /? toont de help.\n• arp: elke netwerkkaart heeft een vast fysiek adres (MAC-adres). Je pc houdt een tabel bij met welk IP-adres bij welk MAC-adres hoort, voor de toestellen op je lokale netwerk: de ARP-tabel. arp -a toont ze.\n• netstat: toont de netwerkverbindingen van je pc en de poorten die gebruikt worden. Een poort is een nummer dat aangeeft voor welk programma netwerkverkeer bestemd is (bv. 443 voor beveiligde websites).\n• netstat 3 vernieuwt de lijst elke 3 seconden (stoppen met Ctrl+C). Open je een browser, dan zie je nieuwe verbindingen verschijnen.\n• netstat -a toont alle verbindingen en open poorten." },
  { v: "Bekijk de help van schtasks.", a: "C:\\> schtasks /?", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true,
    uitleg: "Niet te kennen.\n\nschtasks = schedule tasks: het commando om taken uit de Task Scheduler te beheren vanuit de CLI, zonder het venster. Bv. schtasks /create maakt een taak, schtasks /query toont alle taken.\n\n/? = toon de help: alle opties van het commando, met voorbeelden. Dat werkt bij elk CMD-commando." },
  { v: "Bekijk de documentatie van arp en toon de volledige ARP-tabel.", a: "C:\\> arp /?\nC:\\> arp -a", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true,
    uitleg: "arp /? = toon de help van arp.\narp -a = toon de volledige ARP-tabel: de bekende koppelingen tussen IP- en MAC-adressen.\nNiet te kennen." },
  { v: "Bekijk met netstat de status van je poorten en vernieuw ze elke 3 seconden.", a: "C:\\> netstat\nC:\\> netstat 3", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true,
    uitleg: "netstat = toon de netwerkverbindingen en poorten.\nnetstat 3 = het getal is het interval: elke 3 seconden opnieuw. Stoppen met Ctrl+C.\nNiet te kennen." },
  { v: "Bekijk de status van alle open poorten.", a: "C:\\> netstat -a", o: "schtasks, arp en netstat", extra: true, nietTeKennen: true,
    uitleg: "netstat = toon de netwerkverbindingen en poorten.\n-a = all: ook de poorten die luisteren.\nNiet te kennen." },
];

